};

/// AST 노드 (모든 가능한 AST 노드 타입)
pub const Node = struct {
    tag: Tag,
    loc: Location,
    data: Data,

    pub const Tag = enum {
        // 프로그램
        root,

        // 선언
        fn_decl,
        var_decl,
        const_decl,

        // 문장
        block,
