        array_literal,

        // 타입
        type_primitive,
        type_pointer,
        type_array,
        type_function,
        type_param,           // Generic 타입 파라미터 (T)

        // Generic 관련
        generic_param,        // comptime 파라미터
        comptime_decl,        // comptime 블록

        // 기타
        param,
        arg,
    };

    pub const Data = union {
        // root: []Node,
        // fn_decl, var_decl, const_decl, etc.
        // 일단 단순하게 구현, 나중에 확장

        // 이진 연산자
        binary_op: struct {
            op: BinaryOp,
            lhs: *Node,
            rhs: *Node,
        },

        // 단항 연산자
        unary_op: struct {
            op: UnaryOp,
            operand: *Node,
        },

        // 함수 호출
        call: struct {
            callee: *Node,
            args: []Node,
        },

        // 멤버 접근 (obj.field)
        member_access: struct {
            object: *Node,
            field: []const u8,
        },

        // 배열 인덱싱
        index_access: struct {
            array: *Node,
            index: *Node,
        },

        // 리터럴
        integer: i64,
        float: f64,
        string: []const u8,
        identifier: []const u8,

        // 배열 리터럴
        array_literal: []Node,

        // 식 문장
        expr: *Node,

        // 반환 문
        return_expr: ?*Node,

        // 블록 (복수 문장)
        block: []Node,

        // if 문
        if_stmt: struct {
            condition: *Node,
            then_branch: *Node,
            else_branch: ?*Node,
        },

        // while 루프
        while_stmt: struct {
            condition: *Node,
            body: *Node,
        },

        // for 루프
        for_stmt: struct {
            init: ?*Node,
            condition: ?*Node,
