// 🦎 Phase 3: Generic Type Support - Test Cases
// test/phase3_generic_test.zig: Generic 함수, 구조체 등 테스트

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const Ast = @import("../src/ast.zig");

/// 소스 코드를 파싱하는 헬퍼 함수
fn parseSource(source: []const u8, allocator: std.mem.Allocator) !Ast {
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();
    return try parser.parseProgram();
}

// ========== 1. Generic 함수 기본 파싱 ==========

test "parse_generic_function_simple" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Generic 함수: fn max(comptime T: type, a: T, b: T) T { ... }
    const source = "fn max(comptime T: type, a: T, b: T) T { return a; }";

    const ast = try parseSource(source, allocator);

    // 파싱 성공 확인
    try std.testing.expect(ast.root.tag == .root);

    // 첫 번째 자식이 함수 선언이어야 함
    const fn_node = ast.root.data.block[0];
    try std.testing.expect(fn_node.tag == .fn_decl);

    // 함수 이름 확인
    try std.testing.expect(std.mem.eql(u8, fn_node.data.fn_decl.name, "max"));

    // 파라미터 개수 확인 (3개: T, a, b)
    try std.testing.expect(fn_node.data.fn_decl.params.len == 3);

    // 첫 번째 파라미터: comptime T: type
    const param0 = fn_node.data.fn_decl.params[0];
    try std.testing.expect(std.mem.eql(u8, param0.name, "T"));
    try std.testing.expect(param0.is_comptime == true);

    // 두 번째 파라미터: a: T
    const param1 = fn_node.data.fn_decl.params[1];
    try std.testing.expect(std.mem.eql(u8, param1.name, "a"));
    try std.testing.expect(param1.is_comptime == false);

    // 세 번째 파라미터: b: T
    const param2 = fn_node.data.fn_decl.params[2];
    try std.testing.expect(std.mem.eql(u8, param2.name, "b"));
    try std.testing.expect(param2.is_comptime == false);
}

test "parse_generic_function_with_return_type" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn id(comptime T: type, x: T) T { return x; }";

    const ast = try parseSource(source, allocator);
    const fn_node = ast.root.data.block[0];

    try std.testing.expect(std.mem.eql(u8, fn_node.data.fn_decl.name, "id"));
    try std.testing.expect(fn_node.data.fn_decl.params.len == 2);
    try std.testing.expect(fn_node.data.fn_decl.return_type != null);
}

test "parse_multiple_generic_params" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // 여러 개의 Generic 파라미터
    const source = "fn pair(comptime T: type, comptime U: type, a: T, b: U) i32 { return 0; }";

    const ast = try parseSource(source, allocator);
    const fn_node = ast.root.data.block[0];

    try std.testing.expect(fn_node.data.fn_decl.params.len == 4);

    // 첫 번째: comptime T: type
    try std.testing.expect(fn_node.data.fn_decl.params[0].is_comptime == true);

    // 두 번째: comptime U: type
    try std.testing.expect(fn_node.data.fn_decl.params[1].is_comptime == true);

    // 세 번째: a: T
    try std.testing.expect(fn_node.data.fn_decl.params[2].is_comptime == false);

    // 네 번째: b: U
    try std.testing.expect(fn_node.data.fn_decl.params[3].is_comptime == false);
}

// ========== 2. Regular 함수 (Comptime 파라미터 없음) ==========

test "parse_regular_function_still_works" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn add(a: i32, b: i32) i32 { return a + b; }";

    const ast = try parseSource(source, allocator);
    const fn_node = ast.root.data.block[0];

    try std.testing.expect(fn_node.data.fn_decl.params.len == 2);

    // 모든 파라미터가 comptime이 아니어야 함
    for (fn_node.data.fn_decl.params) |param| {
        try std.testing.expect(param.is_comptime == false);
    }
}

// ========== 3. Generic 함수 호출 (AST 수준) ==========

test "parse_generic_function_call" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Generic 함수 정의 + 호출
    const source =
        \\fn max(comptime T: type, a: T, b: T) T {
        \\    return a;
        \\}
        \\fn main() i32 {
        \\    const x = max(i32, 5, 10);
        \\    return x;
        \\}
    ;

    const ast = try parseSource(source, allocator);

    // 2개의 함수가 파싱되어야 함
    try std.testing.expect(ast.root.data.block.len >= 2);
}

// ========== 4. Comptime 블록 ==========

test "parse_comptime_block" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn main() void {
        \\    comptime {
        \\        const x = 5;
        \\    }
        \\}
    ;

    // 현재는 comptime 블록을 완전히 지원하지 않지만,
    // 적어도 파싱이 실패하지 않아야 함 (또는 에러 처리)
    const ast = try parseSource(source, allocator);
    try std.testing.expect(ast.root.data.block.len >= 1);
}

// ========== 5. Generic with Constraint ==========

test "parse_generic_with_constraint_simplified" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // 현재는 constraint를 구조적으로 지원하지 않으므로,
    // 단순히 파싱이 실패하지 않음을 확인
    const source = "fn max(comptime T: type, a: T, b: T) T { return a; }";

    const ast = try parseSource(source, allocator);
    try std.testing.expect(ast.root.data.block.len >= 1);
}

// ========== 6. Mixed Generic and Regular Parameters ==========

test "parse_mixed_comptime_and_regular_params" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process(comptime T: type, data: []T, len: i32) i32 { return 0; }";

    const ast = try parseSource(source, allocator);
    const fn_node = ast.root.data.block[0];

    try std.testing.expect(fn_node.data.fn_decl.params.len == 3);
    try std.testing.expect(fn_node.data.fn_decl.params[0].is_comptime == true);
    try std.testing.expect(fn_node.data.fn_decl.params[1].is_comptime == false);
    try std.testing.expect(fn_node.data.fn_decl.params[2].is_comptime == false);
}

