     1→// 🦎 Mini Zig Compiler - Phase 2.3: AstGen
     2→// src/astgen.zig: AST → ZIR (Untyped Intermediate Representation)
     3→
     4→const std = @import("std");
     5→const Ast = @import("ast.zig");
     6→const Node = Ast.Node;
     7→const Zir = @import("zir.zig").Zir;
     8→
     9→pub const AstGen = struct {
    10→    zir: *Zir,
    11→    allocator: std.mem.Allocator,
    12→    source: []const u8,
    13→
    14→    pub fn init(allocator: std.mem.Allocator, source: []const u8) !AstGen {
    15→        var zir = try allocator.create(Zir);
    16→        zir.* = Zir.init(allocator);
    17→
    18→        return .{
    19→            .zir = zir,
    20→            .allocator = allocator,
    21→            .source = source,
    22→        };
    23→    }
    24→
    25→    pub fn deinit(self: *AstGen) void {
    26→        self.zir.deinit();
    27→        self.allocator.destroy(self.zir);
    28→    }
    29→
    30→    /// 전체 프로그램 생성
    31→    pub fn genProgram(self: *AstGen, ast: *const Ast) !void {
    32→        // root 노드의 블록 생성
    33→        if (ast.root.data == .block) {
    34→            for (ast.root.data.block) |stmt| {
    35→                _ = try self.genNode(&stmt);
    36→            }
    37→        }
    38→    }
    39→
    40→    /// 노드 생성 (재귀)
    41→    pub fn genNode(self: *AstGen, node: *const Node) !Zir.Ref {
    42→        return switch (node.tag) {
    43→            // 선언
    44→            .fn_decl => self.genFnDecl(node),
    45→            .const_decl => self.genConstDecl(node),
    46→            .var_decl => self.genVarDecl(node),
    47→
    48→            // 문장
    49→            .return_stmt => self.genReturnStmt(node),
    50→            .block => self.genBlock(node),
    51→            .if_stmt => self.genIfStmt(node),
    52→            .while_stmt => self.genWhileStmt(node),
    53→            .expr_stmt => self.genExprStmt(node),
    54→
    55→            // 식
    56→            .binary_op => self.genBinaryOp(node),
    57→            .unary_op => self.genUnaryOp(node),
    58→            .call => self.genCall(node),
