// 🦎 Phase 3.1 Step 3: Sema - Generic Function Analysis Tests
// test/phase3_sema_generic_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const AstGen = @import("../src/astgen.zig").AstGen;
const Sema = @import("../src/sema.zig").Sema;
const Air = @import("../src/air.zig").Air;

/// 소스 코드를 분석하는 헬퍼 함수
fn analyzeSoure(source: []const u8, allocator: std.mem.Allocator) !Sema {
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();
    const ast = try parser.parseProgram();

    var astgen = try AstGen.init(allocator, source);
    defer astgen.deinit();
    try astgen.genProgram(&ast);

    var sema = try Sema.init(allocator, astgen.zir);
    try sema.analyzeProgram();

    return sema;
}

// ========== 1. Generic 함수 등록 ==========

test "sema_generic_function_registration" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn max(comptime T: type, a: T, b: T) T { return a; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // Generic 함수가 등록되었는지 확인
    try std.testing.expect(sema.generic_functions.count() >= 1);

    // "max" 함수가 Generic 함수로 등록됨
    const max_func = sema.generic_functions.get("max");
    try std.testing.expect(max_func != null);
}

test "sema_generic_function_signature" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn pair(comptime T: type, comptime U: type, a: T, b: U) i32 { return 0; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // Generic 함수 확인
    const pair_func = sema.generic_functions.get("pair");
    try std.testing.expect(pair_func != null);

    // Comptime 파라미터 개수 확인 (2개: T, U)
    try std.testing.expect(pair_func.?.comptime_param_names.len == 2);
}

// ========== 2. Regular 함수는 등록 안 함 ==========

test "sema_regular_function_not_registered_as_generic" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn add(a: i32, b: i32) i32 { return a + b; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // 일반 함수는 generic_functions에 등록되지 않음
    try std.testing.expect(sema.generic_functions.count() == 0);
}

// ========== 3. Generic 함수 인스턴시화 ==========

test "sema_generic_function_instantiation" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn max(comptime T: type, a: T, b: T) T { return a; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // Generic 함수 인스턴스 생성: max(i32, 5, 10)
    const instance_name = try sema.instantiateGenericFunction("max", &.{.i32});

    // 인스턴스 이름이 "max_i32"
    try std.testing.expect(std.mem.eql(u8, instance_name, "max_i32"));

    // 인스턴스가 기록됨
    try std.testing.expect(sema.generic_instances.items.len == 1);
}

test "sema_generic_function_multiple_instances" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn max(comptime T: type, a: T, b: T) T { return a; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // 두 개의 인스턴스 생성: max(i32), max(f64)
    _ = try sema.instantiateGenericFunction("max", &.{.i32});
    _ = try sema.instantiateGenericFunction("max", &.{.f64});

    // 두 개의 인스턴스가 기록됨
    try std.testing.expect(sema.generic_instances.items.len == 2);

    // 첫 번째 인스턴스: max_i32
    try std.testing.expect(std.mem.eql(u8, sema.generic_instances.items[0].instance_name, "max_i32"));

    // 두 번째 인스턴스: max_f64
    try std.testing.expect(std.mem.eql(u8, sema.generic_instances.items[1].instance_name, "max_f64"));
}

// ========== 4. 다중 Generic 파라미터 ==========

test "sema_multiple_generic_params" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn pair(comptime T: type, comptime U: type, a: T, b: U) i32 { return 0; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // 인스턴스 생성: pair(i32, f64)
    const instance_name = try sema.instantiateGenericFunction("pair", &.{ .i32, .f64 });

    // 인스턴스 이름이 "pair_i32_f64"
    try std.testing.expect(std.mem.eql(u8, instance_name, "pair_i32_f64"));
}

// ========== 5. AIR 생성 검증 ==========

test "sema_generates_air_for_generic_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn max(comptime T: type, a: T, b: T) T { return a; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // AIR 명령어가 생성됨
    try std.testing.expect(sema.air.instructions.items.len > 0);

    // 첫 번째 명령어는 fn_begin
    try std.testing.expect(sema.air.instructions.items[0] == .fn_begin);
}

// ========== 6. Generic 함수 호출 처리 ==========

test "sema_handle_generic_call" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn max(comptime T: type, a: T, b: T) T { return a; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // Generic 함수 호출 처리
    try sema.handleGenericCall("max", &.{.i32}, &.{});

    // 인스턴스가 생성됨
    try std.testing.expect(sema.generic_instances.items.len >= 1);
}

// ========== 7. 다중 Generic 함수 ==========

test "sema_multiple_generic_functions" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn max(comptime T: type, a: T, b: T) T { return a; }
        \\fn min(comptime T: type, a: T, b: T) T { return a; }
    ;

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // 두 개의 Generic 함수가 등록됨
    try std.testing.expect(sema.generic_functions.count() == 2);

    // "max"와 "min" 함수 확인
    try std.testing.expect(sema.generic_functions.get("max") != null);
    try std.testing.expect(sema.generic_functions.get("min") != null);
}

// ========== 8. Generic + Regular 함수 혼합 ==========

test "sema_mixed_generic_and_regular_functions" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn add(a: i32, b: i32) i32 { return a + b; }
        \\fn max(comptime T: type, a: T, b: T) T { return a; }
    ;

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // Generic 함수는 1개 ("max")
    try std.testing.expect(sema.generic_functions.count() == 1);

    // AIR 명령어는 2개 함수 모두 포함
    try std.testing.expect(sema.air.instructions.items.len > 0);
}

// ========== 9. Generic 함수 이름 추출 ==========

test "sema_generic_function_name_extraction" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn custom(comptime T: type, x: T) T { return x; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // "custom" 함수가 등록됨
    const custom_func = sema.generic_functions.get("custom");
    try std.testing.expect(custom_func != null);

    // 함수 이름이 "custom"
    try std.testing.expect(std.mem.eql(u8, custom_func.?.name, "custom"));
}

// ========== 10. Instance Tracking ==========

test "sema_instance_tracking" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn max(comptime T: type, a: T, b: T) T { return a; }";

    var sema = try analyzeSoure(source, allocator);
    defer sema.deinit();

    // 세 개의 다른 타입으로 인스턴시화
    _ = try sema.instantiateGenericFunction("max", &.{.i32});
    _ = try sema.instantiateGenericFunction("max", &.{.i64});
    _ = try sema.instantiateGenericFunction("max", &.{.f64});

    // 세 개의 인스턴스가 기록됨
    try std.testing.expect(sema.generic_instances.items.len == 3);

    // 원본 함수 이름이 모두 "max"
    for (sema.generic_instances.items) |instance| {
        try std.testing.expect(std.mem.eql(u8, instance.original_name, "max"));
    }
}

