# 🦎 Phase 3.2: Union & Enum Types - 상세 구현 계획

**날짜**: 2026-03-11 17:30 UTC+9
**상태**: 계획 단계
**예상 기간**: 2주 (3-4단계, 각 단계 3-4일)
**목표**: Union/Enum 타입 완전 지원

---

## 📋 Phase 3.2 개요

Union과 Enum은 Zig의 고급 타입 시스템 핵심입니다:

```zig
// Union Type (Tagged Union)
union(enum) Result(comptime T: type) {
    ok: T,
    err: []const u8,
}

// Usage
var r: Result(i32) = .{ .ok = 42 };
if (r == .ok) {
    const value = r.ok;
}

// Enum Type
enum Animal {
    dog,
    cat,
    bird,
}

// Tagged Enum with Values
enum Value {
    int(i32),
    float(f64),
    string([]const u8),
}
```

---

## 🎯 구현 전략 (3 Step)

```
┌──────────────────────────────────────────────┐
│ Step 1: AST & Parser 확장 (4일)             │
├──────────────────────────────────────────────┤
│ • union_tag, union_decl, enum_tag, enum_decl│
│ • union { a: T, b: U } 파싱               │
│ • enum { x, y, z } 파싱                    │
│ • union(enum) tagged union 파싱            │
│ • 테스트: 15개                              │
└──────────────────────────────────────────────┘
               ↓
┌──────────────────────────────────────────────┐
│ Step 2: AstGen 확장 (4일)                   │
├──────────────────────────────────────────────┤
│ • union_begin, union_field ZIR Instruction │
│ • enum_begin, enum_value ZIR Instruction   │
│ • Union 필드 메타데이터 저장               │
│ • Enum 값 목록 저장                        │
│ • 테스트: 12개                              │
└──────────────────────────────────────────────┘
               ↓
┌──────────────────────────────────────────────┐
│ Step 3: Sema 분석 (4일)                    │
├──────────────────────────────────────────────┤
│ • Union 타입 검증                          │
│ • Union 필드 접근 분석 (tagged union)      │
│ • Enum 타입 검증                           │
│ • Tag 기반 타입 축소 (type narrowing)      │
│ • 테스트: 13개                              │
└──────────────────────────────────────────────┘
```

---

## 📝 Step 1: AST & Parser 확장

### 1.1 AST 노드 추가

**파일**: `src/ast.zig`

```zig
// Union Type Node
pub const UnionType = struct {
    name: []const u8,
    fields: []const UnionField,
    is_tagged: bool = false,  // union(enum) 여부
    tag_type: ?*Node = null,  // enum type (if tagged)
    location: Location,
};

pub const UnionField = struct {
    name: []const u8,
    type_node: *Node,
    location: Location,
};

// Enum Type Node
pub const EnumType = struct {
    name: []const u8,
    fields: []const EnumField,
    is_tagged: bool = false,  // enum with values
    location: Location,
};

pub const EnumField = struct {
    name: []const u8,
    value: ?*Node = null,  // Optional value expression
    location: Location,
};

// Node.Tag에 추가
pub const Tag = enum {
    // ... 기존 태그들
    union_type,
    enum_type,
    union_field,
    enum_field,
};
```

### 1.2 Parser 함수 추가

**파일**: `src/parser.zig`

```zig
// parseUnionType() 함수
// 입력: "union Result(T) { ok: i32, err: string }"
// 출력: UnionType AST 노드
fn parseUnionType(self: *Parser) !*Node {
    try self.expect(.union_keyword);
    const name = try self.parseIdentifier();

    var fields = std.ArrayList(ast.UnionField).init(self.allocator);
    defer fields.deinit();

    try self.expect(.lbrace);
    while (!self.match(.rbrace)) {
        const field_name = try self.parseIdentifier();
        try self.expect(.colon);
        const field_type = try self.parseTypeExpression();

        try fields.append(.{
            .name = field_name,
            .type_node = field_type,
            .location = field_type.location,
        });

        if (!self.check(.rbrace)) {
            try self.expect(.comma);
        }
    }

    const node = try self.allocator.create(ast.Node);
    node.* = .{
        .tag = .union_type,
        .data = .{
            .union_type = .{
                .name = name,
                .fields = try self.allocator.dupe(ast.UnionField, fields.items),
                .location = /* ... */,
            },
        },
    };
    return node;
}

// parseEnumType() 함수
// 입력: "enum Animal { dog, cat, bird }"
// 출력: EnumType AST 노드
fn parseEnumType(self: *Parser) !*Node {
    try self.expect(.enum_keyword);
    const name = try self.parseIdentifier();

    var fields = std.ArrayList(ast.EnumField).init(self.allocator);
    defer fields.deinit();

    try self.expect(.lbrace);
    while (!self.match(.rbrace)) {
        const field_name = try self.parseIdentifier();
        const field_value: ?*ast.Node = if (self.match(.lparen)) {
            const expr = try self.parseExpression();
            try self.expect(.rparen);
            expr
        } else null;

        try fields.append(.{
            .name = field_name,
            .value = field_value,
            .location = /* ... */,
        });

        if (!self.check(.rbrace)) {
            try self.expect(.comma);
        }
    }

    const node = try self.allocator.create(ast.Node);
    node.* = .{
        .tag = .enum_type,
        .data = .{
            .enum_type = .{
                .name = name,
                .fields = try self.allocator.dupe(ast.EnumField, fields.items),
                .location = /* ... */,
            },
        },
    };
    return node;
}
```

### 1.3 Parser 통합

**파일**: `src/parser.zig`

```zig
fn parseTypeExpression(self: *Parser) !*Node {
    if (self.match(.union_keyword)) {
