// 🦎 Phase 3.2 Step 1: Union & Enum Parser Tests
// test/phase3_union_enum_parser_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const ast = @import("../src/ast.zig");

/// 소스 코드를 파싱하는 헬퍼 함수
fn parseSource(source: []const u8, allocator: std.mem.Allocator) !ast.Ast {
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();

    return try parser.parseProgram();
}

// ========== 1. Simple Union Parsing ==========

test "parse_simple_union" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "union Result { ok: i32, err: string }";

    var ast_result = try parseSource(source, allocator);
    defer ast_result.deinit();

    const root = &ast_result.root;
    try std.testing.expect(root.data.block.len > 0);

    const first_node = &root.data.block[0];
    try std.testing.expect(first_node.tag == .union_type);
    try std.testing.expectEqualSlices(u8, first_node.data.union_type_data.name, "Result");
    try std.testing.expect(first_node.data.union_type_data.fields.len == 2);
}

test "parse_union_single_field" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "union Option { value: i32 }";

    var ast_result = try parseSource(source, allocator);
    defer ast_result.deinit();

    const root = &ast_result.root;
    const union_node = &root.data.block[0];

    try std.testing.expect(union_node.tag == .union_type);
    try std.testing.expectEqualSlices(u8, union_node.data.union_type_data.name, "Option");
    try std.testing.expect(union_node.data.union_type_data.fields.len == 1);
    try std.testing.expectEqualSlices(u8, union_node.data.union_type_data.fields[0].name, "value");
}

test "parse_union_multiple_fields" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "union Value { int: i32, float: f64, string: string }";

    var ast_result = try parseSource(source, allocator);
    defer ast_result.deinit();

    const root = &ast_result.root;
    const union_node = &root.data.block[0];

    try std.testing.expect(union_node.tag == .union_type);
    try std.testing.expect(union_node.data.union_type_data.fields.len == 3);
    try std.testing.expectEqualSlices(u8, union_node.data.union_type_data.fields[0].name, "int");
    try std.testing.expectEqualSlices(u8, union_node.data.union_type_data.fields[1].name, "float");
    try std.testing.expectEqualSlices(u8, union_node.data.union_type_data.fields[2].name, "string");
}

// ========== 2. Simple Enum Parsing ==========

test "parse_simple_enum" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "enum Animal { dog, cat, bird }";

    var ast_result = try parseSource(source, allocator);
    defer ast_result.deinit();

    const root = &ast_result.root;
    try std.testing.expect(root.data.block.len > 0);

    const first_node = &root.data.block[0];
    try std.testing.expect(first_node.tag == .enum_type);
    try std.testing.expectEqualSlices(u8, first_node.data.enum_type_data.name, "Animal");
    try std.testing.expect(first_node.data.enum_type_data.fields.len == 3);
}

test "parse_enum_single_value" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "enum Status { active }";

    var ast_result = try parseSource(source, allocator);
    defer ast_result.deinit();

    const root = &ast_result.root;
    const enum_node = &root.data.block[0];

    try std.testing.expect(enum_node.tag == .enum_type);
    try std.testing.expectEqualSlices(u8, enum_node.data.enum_type_data.name, "Status");
    try std.testing.expect(enum_node.data.enum_type_data.fields.len == 1);
    try std.testing.expectEqualSlices(u8, enum_node.data.enum_type_data.fields[0].name, "active");
}

// ========== 3. Enum with Values ==========

test "parse_enum_with_integer_values" {
