// 🦎 Phase 3.3 Step 2: Comptime Programming - AstGen Tests
// test/phase3_comptime_astgen_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const AstGen = @import("../src/astgen.zig").AstGen;
const Zir = @import("../src/zir.zig").Zir;
const ast = @import("../src/ast.zig");

/// 소스 코드를 AstGen으로 변환하는 헬퍼 함수
fn generateZir(source: []const u8, allocator: std.mem.Allocator) !Zir {
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();
    const ast_result = try parser.parseProgram();

    var astgen = try AstGen.init(allocator, source);
    try astgen.genProgram(&ast_result);

    return astgen.zir;
}

// ========== 1. Simple Const Expression ==========

test "astgen_const_simple_generates_const_expr" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const X = 42;";

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    // ZIR instructions should contain const_expr (for const_decl, which now maps to const_expr)
    // or similar constant handling
    try std.testing.expect(zir.instructions.items.len > 0);
}

test "astgen_const_with_type" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const X: i32 = 42;";

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    try std.testing.expect(zir.instructions.items.len > 0);
}

// ========== 2. Comptime Block ==========

test "astgen_comptime_block_generates_comptime_begin" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "comptime {};";

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    // ZIR instructions should contain comptime_begin
    var found_comptime_begin = false;
    for (zir.instructions.items) |inst| {
        if (inst == .comptime_begin) {
            found_comptime_begin = true;
        }
    }
    try std.testing.expect(found_comptime_begin);
}

test "astgen_comptime_block_with_const" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\comptime {
        \\  const X = 10;
        \\}
    ;

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    var found_comptime_begin = false;
    for (zir.instructions.items) |inst| {
        if (inst == .comptime_begin) {
            found_comptime_begin = true;
        }
    }
    try std.testing.expect(found_comptime_begin);
}

// ========== 3. Const Expression in ZIR ==========

test "astgen_const_expr_stores_name" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const MY_CONST = 42;";

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    // String pool should contain "MY_CONST"
    try std.testing.expect(zir.strings.count() > 0);
}

test "astgen_multiple_comptime_blocks" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\comptime {
        \\  const A = 5;
        \\}
        \\comptime {
        \\  const B = 10;
        \\}
    ;

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    var comptime_count: u32 = 0;
    for (zir.instructions.items) |inst| {
        if (inst == .comptime_begin) {
            comptime_count += 1;
        }
    }
    try std.testing.expect(comptime_count == 2);
}

// ========== 4. Comptime with Expressions ==========

test "astgen_comptime_arithmetic_expression" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const SUM = 10 + 20;";

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    var found_binary_op = false;
    for (zir.instructions.items) |inst| {
        if (inst == .binary_op) {
            found_binary_op = true;
        }
    }
    try std.testing.expect(found_binary_op);
}

test "astgen_comptime_string_pool_integration" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\const X = 42;
        \\const Y = 100;
    ;

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    // Both "X" and "Y" should be in string pool
    try std.testing.expect(zir.strings.count() >= 2);
}

// ========== 5. Comptime Block with Multiple Statements ==========

test "astgen_comptime_block_multiple_statements" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\comptime {
