    const source =
        \\comptime {
        \\  const X = 10;
        \\  comptime {
        \\    const Y = X + 5;
        \\  }
        \\}
    ;

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    var comptime_count: u32 = 0;
    for (zir.instructions.items) |inst| {
        if (inst == .comptime_begin) {
            comptime_count += 1;
        }
    }
    try std.testing.expect(comptime_count >= 2);
}

// ========== 7. Value Reference in Const ==========

test "astgen_const_with_referenced_value" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\const A = 5;
        \\const B = A + 3;
    ;

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    try std.testing.expect(zir.instructions.items.len > 0);
}

// ========== 8. Comptime Block in Function ==========

test "astgen_comptime_with_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\comptime {
        \\  fn getValue() i32 { return 42; }
        \\}
    ;

    const zir = try generateZir(source, allocator);
    defer zir.deinit();

    var found_comptime_begin = false;
    var found_fn_begin = false;
    for (zir.instructions.items) |inst| {
        if (inst == .comptime_begin) {
            found_comptime_begin = true;
        }
        if (inst == .fn_begin) {
            found_fn_begin = true;
        }
    }
    try std.testing.expect(found_comptime_begin);
    try std.testing.expect(found_fn_begin);
}

