     1→// 🦎 Mini Zig Compiler - Phase 2.3: AstGen
     2→// src/astgen.zig: AST → ZIR (Untyped Intermediate Representation)
     3→
     4→const std = @import("std");
     5→const Ast = @import("ast.zig");
     6→const Node = Ast.Node;
     7→const Zir = @import("zir.zig").Zir;
     8→
     9→pub const AstGen = struct {
    10→    zir: *Zir,
    11→    allocator: std.mem.Allocator,
    12→    source: []const u8,
    13→
    14→    pub fn init(allocator: std.mem.Allocator, source: []const u8) !AstGen {
    15→        var zir = try allocator.create(Zir);
    16→        zir.* = Zir.init(allocator);
    17→
    18→        return .{
    19→            .zir = zir,
    20→            .allocator = allocator,
    21→            .source = source,
    22→        };
    23→    }
    24→
    25→    pub fn deinit(self: *AstGen) void {
    26→        self.zir.deinit();
    27→        self.allocator.destroy(self.zir);
    28→    }
    29→
    30→    /// 전체 프로그램 생성
    31→    pub fn genProgram(self: *AstGen, ast: *const Ast) !void {
    32→        // root 노드의 블록 생성
    33→        if (ast.root.data == .block) {
    34→            for (ast.root.data.block) |stmt| {
    35→                _ = try self.genNode(&stmt);
    36→            }
    37→        }
    38→    }
    39→
    40→    /// 노드 생성 (재귀)
    41→    pub fn genNode(self: *AstGen, node: *const Node) !Zir.Ref {
    42→        return switch (node.tag) {
    43→            // 선언
    44→            .fn_decl => self.genFnDecl(node),
    45→            .const_decl => self.genConstDecl(node),
    46→            .var_decl => self.genVarDecl(node),
    47→
    48→            // Phase 3.2: Union/Enum
    49→            .union_type => self.genUnionType(node),
    50→            .enum_type => self.genEnumType(node),
    51→
    52→            // Phase 3.3: Comptime Programming
    53→            .comptime_block_expr => self.genComptimeBlockExpr(node),
    54→            .const_expr => self.genConstExpr(node),
    55→
    56→            // 문장
    57→            .return_stmt => self.genReturnStmt(node),
    58→            .block => self.genBlock(node),
    59→            .if_stmt => self.genIfStmt(node),
    60→            .while_stmt => self.genWhileStmt(node),
    61→            .expr_stmt => self.genExprStmt(node),
    62→
    63→            // 식
    64→            .binary_op => self.genBinaryOp(node),
    65→            .unary_op => self.genUnaryOp(node),
    66→            .call => self.genCall(node),
    67→            .integer_literal => self.genIntegerLiteral(node),
    68→            .float_literal => self.genFloatLiteral(node),
    69→            .string_literal => self.genStringLiteral(node),
    70→            .identifier => self.genIdentifier(node),
    71→            .array_literal => self.genArrayLiteral(node),
    72→            .index_access => self.genIndexAccess(node),
    73→            .member_access => self.genMemberAccess(node),
    74→            .grouped_expr => self.genNode(node.data.expr),
    75→
    76→            // 기타
    77→            .var_assign => self.genVarAssign(node),
    78→
    79→            else => error.UnhandledNodeType,
    80→        };
    81→    }
    82→
    83→    /// 함수 선언 생성
    84→    fn genFnDecl(self: *AstGen, node: *const Node) !Zir.Ref {
    85→        const fn_decl = node.data.fn_decl;
    86→
    87→        // 함수 이름 추가
    88→        const name_index = try self.zir.addString(fn_decl.name);
    89→
    90→        // 파라미터 생성
    91→        var params = std.ArrayList(Zir.Ref).init(self.allocator);
    92→        defer params.deinit();
    93→
    94→        // Comptime 파라미터 개수 세기
    95→        var comptime_param_count: u32 = 0;
    96→        for (fn_decl.params) |param| {
    97→            if (param.is_comptime) {
    98→                comptime_param_count += 1;
    99→            }
   100→            // 파라미터 이름을 ZIR 문자열로 등록
   101→            _ = try self.zir.addString(param.name);
   102→            // 파라미터 ref는 0으로 설정 (나중에 확장)
   103→            try params.append(0);
   104→        }
   105→
   106→        // Generic 함수인지 확인
   107→        if (comptime_param_count > 0) {
   108→            // Generic 함수: generic_fn_begin 사용
   109→            const fn_begin_ref = try self.zir.addInstruction(.{
   110→                .generic_fn_begin = .{
   111→                    .name_index = name_index,
   112→                    .comptime_param_count = comptime_param_count,
   113→                    .params = try self.allocator.dupe(Zir.Ref, params.items),
   114→                },
   115→            });
   116→
   117→            // 함수 본체 생성
   118→            _ = try self.genNode(fn_decl.body);
   119→
   120→            // 함수 끝
   121→            _ = try self.zir.addInstruction(.fn_end);
   122→
   123→            return fn_begin_ref;
   124→        } else {
   125→            // 일반 함수: fn_begin 사용
   126→            const fn_begin_ref = try self.zir.addInstruction(.{
   127→                .fn_begin = .{
   128→                    .name_index = name_index,
   129→                    .params = try self.allocator.dupe(Zir.Ref, params.items),
   130→                },
   131→            });
   132→
   133→            // 함수 본체 생성
   134→            _ = try self.genNode(fn_decl.body);
   135→
   136→            // 함수 끝
   137→            _ = try self.zir.addInstruction(.fn_end);
   138→
   139→            return fn_begin_ref;
   140→        }
   141→    }
   142→
   143→    /// 상수 선언 생성
   144→    fn genConstDecl(self: *AstGen, node: *const Node) !Zir.Ref {
   145→        const const_decl = node.data.const_decl;
   146→
   147→        // 값 생성
   148→        const value_ref = try self.genNode(const_decl.value);
   149→
   150→        // 변수 이름 추가
   151→        const name_index = try self.zir.addString(const_decl.name);
   152→
   153→        // store 명령어 생성
   154→        return try self.zir.addInstruction(.{
   155→            .store_var = .{
   156→                .name_index = name_index,
   157→                .value = value_ref,
   158→            },
   159→        });
   160→    }
   161→
   162→    /// 변수 선언 생성
   163→    fn genVarDecl(self: *AstGen, node: *const Node) !Zir.Ref {
   164→        const var_decl = node.data.var_decl;
   165→
   166→        // 초기값이 있으면 생성
   167→        var value_ref: Zir.Ref = 0;
   168→        if (var_decl.initial_value) |init| {
   169→            value_ref = try self.genNode(init);
   170→        }
   171→
   172→        // 변수 이름 추가
   173→        const name_index = try self.zir.addString(var_decl.name);
   174→
   175→        // store 명령어 생성
   176→        return try self.zir.addInstruction(.{
   177→            .store_var = .{
   178→                .name_index = name_index,
   179→                .value = value_ref,
   180→            },
   181→        });
   182→    }
   183→
   184→    /// return 문 생성
   185→    fn genReturnStmt(self: *AstGen, node: *const Node) !Zir.Ref {
   186→        if (node.data.return_expr) |expr| {
   187→            const value = try self.genNode(expr);
   188→            return try self.zir.addInstruction(.{ .return_val = value });
   189→        } else {
   190→            return try self.zir.addInstruction(.{ .return_val = null });
   191→        }
   192→    }
   193→
   194→    /// 블록 생성
   195→    fn genBlock(self: *AstGen, node: *const Node) !Zir.Ref {
   196→        const block_label: u32 = @intCast(self.zir.instructions.items.len);
   197→
   198→        _ = try self.zir.addInstruction(.{
   199→            .block_begin = .{ .label = block_label },
   200→        });
   201→
   202→        var last_ref: Zir.Ref = 0;
   203→        for (node.data.block) |stmt| {
   204→            last_ref = try self.genNode(&stmt);
   205→        }
   206→
   207→        _ = try self.zir.addInstruction(.block_end);
   208→
   209→        return last_ref;
   210→    }
   211→
   212→    /// if 문 생성
   213→    fn genIfStmt(self: *AstGen, node: *const Node) !Zir.Ref {
   214→        const if_stmt = node.data.if_stmt;
   215→
   216→        // 조건 생성
   217→        const cond_ref = try self.genNode(if_stmt.condition);
   218→
   219→        // then 분기 생성
   220→        const then_ref = try self.genNode(if_stmt.then_branch);
   221→
   222→        // else 분기 생성 (있으면)
   223→        var else_ref: ?Zir.Ref = null;
   224→        if (if_stmt.else_branch) |else_br| {
   225→            else_ref = try self.genNode(else_br);
   226→        }
   227→
   228→        return try self.zir.addInstruction(.{
   229→            .cond_br = .{
   230→                .cond = cond_ref,
   231→                .then_block = then_ref,
   232→                .else_block = else_ref,
   233→            },
   234→        });
   235→    }
   236→
   237→    /// while 루프 생성
   238→    fn genWhileStmt(self: *AstGen, node: *const Node) !Zir.Ref {
   239→        const while_stmt = node.data.while_stmt;
   240→
   241→        const loop_label: u32 = @intCast(self.zir.instructions.items.len);
   242→
   243→        _ = try self.zir.addInstruction(.{
   244→            .loop_begin = .{ .label = loop_label },
   245→        });
   246→
   247→        // 조건 생성
   248→        const cond_ref = try self.genNode(while_stmt.condition);
   249→
   250→        // 본체 생성
   251→        _ = try self.genNode(while_stmt.body);
   252→
   253→        _ = try self.zir.addInstruction(.loop_end);
   254→
   255→        return cond_ref;
   256→    }
   257→
   258→    /// 식 문장 생성
   259→    fn genExprStmt(self: *AstGen, node: *const Node) !Zir.Ref {
   260→        return self.genNode(node.data.expr);
   261→    }
   262→
   263→    /// 변수 할당 생성
   264→    fn genVarAssign(self: *AstGen, node: *const Node) !Zir.Ref {
   265→        const assign = node.data.var_assign;
   266→
   267→        // 값 생성
   268→        const value_ref = try self.genNode(assign.value);
   269→
   270→        // 변수 이름 추출
   271→        if (assign.target.tag == .identifier) {
   272→            const name = assign.target.data.identifier;
   273→            const name_index = try self.zir.addString(name);
   274→
   275→            return try self.zir.addInstruction(.{
   276→                .store_var = .{
   277→                    .name_index = name_index,
   278→                    .value = value_ref,
   279→                },
   280→            });
   281→        }
   282→
   283→        return error.InvalidAssignmentTarget;
   284→    }
   285→
   286→    /// 이진 연산자 생성
   287→    fn genBinaryOp(self: *AstGen, node: *const Node) !Zir.Ref {
   288→        const binary_op = node.data.binary_op;
   289→
   290→        // 좌측 및 우측 식 생성
   291→        const lhs = try self.genNode(binary_op.lhs);
   292→        const rhs = try self.genNode(binary_op.rhs);
   293→
   294→        // BinaryOp을 Zir.BinaryOp로 변환
   295→        const zir_op = astBinaryOpToZirBinaryOp(binary_op.op);
   296→
   297→        return try self.zir.addInstruction(.{
   298→            .binary_op = .{
   299→                .op = zir_op,
   300→                .lhs = lhs,
   301→                .rhs = rhs,
   302→            },
   303→        });
   304→    }
   305→
   306→    /// 단항 연산자 생성
   307→    fn genUnaryOp(self: *AstGen, node: *const Node) !Zir.Ref {
   308→        const unary_op = node.data.unary_op;
   309→
   310→        // 피연산자 생성
   311→        const operand = try self.genNode(unary_op.operand);
   312→
   313→        // UnaryOp를 Zir.UnaryOp로 변환
   314→        const zir_op = astUnaryOpToZirUnaryOp(unary_op.op);
   315→
   316→        return try self.zir.addInstruction(.{
   317→            .unary_op = .{
   318→                .op = zir_op,
   319→                .operand = operand,
   320→            },
   321→        });
   322→    }
   323→
   324→    /// 함수 호출 생성
   325→    fn genCall(self: *AstGen, node: *const Node) !Zir.Ref {
   326→        const call = node.data.call;
   327→
   328→        // 호출 대상 생성
   329→        const callee = try self.genNode(call.callee);
   330→
   331→        // 인자들 생성
   332→        var args = std.ArrayList(Zir.Ref).init(self.allocator);
   333→        defer args.deinit();
   334→
   335→        for (call.args) |arg| {
   336→            try args.append(try self.genNode(&arg));
   337→        }
   338→
   339→        return try self.zir.addInstruction(.{
   340→            .call = .{
   341→                .callee = callee,
   342→                .args = try self.allocator.dupe(Zir.Ref, args.items),
   343→            },
   344→        });
   345→    }
   346→
   347→    /// 정수 리터럴 생성
   348→    fn genIntegerLiteral(self: *AstGen, node: *const Node) !Zir.Ref {
   349→        return try self.zir.addInstruction(.{
   350→            .load_int = .{ .value = node.data.integer },
   351→        });
   352→    }
   353→
   354→    /// 부동소수점 리터럴 생성
   355→    fn genFloatLiteral(self: *AstGen, node: *const Node) !Zir.Ref {
   356→        return try self.zir.addInstruction(.{
   357→            .load_float = .{ .value = node.data.float },
   358→        });
   359→    }
   360→
   361→    /// 문자열 리터럴 생성
   362→    fn genStringLiteral(self: *AstGen, node: *const Node) !Zir.Ref {
   363→        const index = try self.zir.addString(node.data.string);
   364→        return try self.zir.addInstruction(.{
   365→            .load_string = .{ .index = index },
   366→        });
   367→    }
   368→
   369→    /// 식별자 생성
   370→    fn genIdentifier(self: *AstGen, node: *const Node) !Zir.Ref {
   371→        const name_index = try self.zir.addString(node.data.identifier);
   372→        return try self.zir.addInstruction(.{
   373→            .load_var = .{ .name_index = name_index },
   374→        });
   375→    }
   376→
   377→    /// 배열 리터럴 생성
   378→    fn genArrayLiteral(self: *AstGen, node: *const Node) !Zir.Ref {
   379→        var elements = std.ArrayList(Zir.Ref).init(self.allocator);
   380→        defer elements.deinit();
   381→
   382→        for (node.data.array_literal) |elem| {
   383→            try elements.append(try self.genNode(&elem));
   384→        }
   385→
   386→        return try self.zir.addInstruction(.{
   387→            .array_literal = .{
   388→                .elements = try self.allocator.dupe(Zir.Ref, elements.items),
   389→            },
   390→        });
   391→    }
   392→
   393→    /// 배열 인덱싱 생성
   394→    fn genIndexAccess(self: *AstGen, node: *const Node) !Zir.Ref {
   395→        const index_access = node.data.index_access;
   396→
   397→        const array = try self.genNode(index_access.array);
   398→        const index = try self.genNode(index_access.index);
   399→
   400→        return try self.zir.addInstruction(.{
   401→            .index_access = .{
   402→                .array = array,
   403→                .index = index,
   404→            },
   405→        });
   406→    }
   407→
   408→    /// 멤버 접근 생성
   409→    fn genMemberAccess(self: *AstGen, node: *const Node) !Zir.Ref {
   410→        const member_access = node.data.member_access;
   411→
   412→        const object = try self.genNode(member_access.object);
   413→        const field_index = try self.zir.addString(member_access.field);
   414→
   415→        return try self.zir.addInstruction(.{
   416→            .member_access = .{
   417→                .object = object,
   418→                .field_index = field_index,
   419→            },
   420→        });
   421→    }
   422→};
   423→
   424→/// Ast.BinaryOp를 Zir.BinaryOp로 변환
   425→fn astBinaryOpToZirBinaryOp(op: Ast.BinaryOp) Zir.BinaryOp {
   426→    return switch (op) {
   427→        .add => .add,
   428→        .subtract => .sub,
   429→        .multiply => .mul,
   430→        .divide => .div,
   431→        .modulo => .mod,
   432→        .equal => .eq,
   433→        .not_equal => .ne,
   434→        .less => .lt,
   435→        .less_equal => .le,
   436→        .greater => .gt,
   437→        .greater_equal => .ge,
   438→        .logical_and => .logical_and,
   439→        .logical_or => .logical_or,
   440→        .bitwise_and => .bitwise_and,
   441→        .bitwise_or => .bitwise_or,
   442→        .bitwise_xor => .bitwise_xor,
   443→        .lshift => .lshift,
   444→        .rshift => .rshift,
   445→    };
   446→}
   447→
   448→/// Ast.UnaryOp를 Zir.UnaryOp로 변환
   449→fn astUnaryOpToZirUnaryOp(op: Ast.UnaryOp) Zir.UnaryOp {
   450→    return switch (op) {
   451→        .negate => .negate,
   452→        .not => .not,
   453→        .bitwise_not => .bitwise_not,
   454→    };
   455→}
   456→
   457→/// Union 타입 생성 (Phase 3.2)
   458→fn genUnionType(self: *AstGen, node: *const Node) !Zir.Ref {
   459→    const union_data = node.data.union_type_data;
   460→
   461→    // Union 이름 추가
   462→    const name_index = try self.zir.addString(union_data.name);
   463→
   464→    // 각 필드 생성
   465→    var field_refs = std.ArrayList(Zir.Ref).init(self.allocator);
   466→    defer field_refs.deinit();
   467→
   468→    for (union_data.fields) |field| {
   469→        const field_name_index = try self.zir.addString(field.name);
   470→        const field_type_ref = try self.genNode(field.type_node);
   471→
   472→        const field_ref = try self.zir.addInstruction(.{
   473→            .union_field = .{
   474→                .field_name_index = field_name_index,
   475→                .field_type = field_type_ref,
   476→            },
   477→        });
   478→        try field_refs.append(field_ref);
   479→    }
   480→
   481→    // Union begin 명령어 생성
   482→    const union_begin_ref = try self.zir.addInstruction(.{
   483→        .union_begin = .{
   484→            .name_index = name_index,
   485→            .field_count = @intCast(u32, union_data.fields.len),
   486→            .is_tagged = union_data.is_tagged,
   487→        },
   488→    });
   489→
   490→    return union_begin_ref;
   491→}
   492→
   493→/// Enum 타입 생성 (Phase 3.2)
   494→fn genEnumType(self: *AstGen, node: *const Node) !Zir.Ref {
   495→    const enum_data = node.data.enum_type_data;
   496→
   497→    // Enum 이름 추가
   498→    const name_index = try self.zir.addString(enum_data.name);
   499→
   500→    // 각 값 생성
   501→    var value_refs = std.ArrayList(Zir.Ref).init(self.allocator);
   502→    defer value_refs.deinit();
   503→
   504→    for (enum_data.fields) |field| {
   505→        const value_name_index = try self.zir.addString(field.name);
   506→        const value_ref: ?Zir.Ref = if (field.value != null)
   507→            try self.genNode(field.value.?)
   508→        else null;
   509→
   510→        const field_ref = try self.zir.addInstruction(.{
   511→            .enum_value = .{
   512→                .value_name_index = value_name_index,
   513→                .value = value_ref,
   514→            },
   515→        });
   516→        try value_refs.append(field_ref);
   517→    }
   518→
