test "astgen_overload_preserves_signatures" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn calculate(x: i32, y: i32) i32 { return x + y; }
