fn typesEqual(self: *Sema, t1: AirType, t2: AirType) bool {
    return switch (t1) {
        .integer => t2 == .integer,
        .float => t2 == .float,
        .string => t2 == .string,
        .boolean => t2 == .boolean,
        .unknown => true,  // unknown은 모든 타입과 매칭
