// 🦎 Phase 3.4 Step 3: Function Overloading - Sema Tests
// test/phase3_overload_sema_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const AstGen = @import("../src/astgen.zig").AstGen;
const Sema = @import("../src/sema.zig").Sema;
const AirType = @import("../src/air.zig").Type;
const Zir = @import("../src/zir.zig").Zir;

/// 소스 코드를 Sema 분석까지 수행하는 헬퍼 함수
fn compileToSema(source: []const u8, allocator: std.mem.Allocator) !*Sema {
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();
    const ast = try parser.parseProgram();

    var astgen = try AstGen.init(allocator, source);
    try astgen.genProgram(&ast);
    defer astgen.deinit();

    var sema = try allocator.create(Sema);
    sema.* = try Sema.init(allocator, astgen.zir);
    return sema;
}

// ========== 1. Basic Exact Matching ==========

test "sema_exact_match_overload" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn add(a: i32, b: i32) i32 { return a + b; }
        \\fn add(a: f64, b: f64) f64 { return a + b; }
    ;

    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    // overload_groups에 "add" 그룹이 있어야 함
    try std.testing.expect(sema.overload_groups.contains("add"));

    // "add" 오버로드 그룹 조회
    const signatures = sema.overload_groups.get("add").?;
    try std.testing.expect(signatures.len == 2);
}

test "sema_exact_match_multiple_types" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn process(x: i32) i32 { return x; }
        \\fn process(x: f64) f64 { return x; }
        \\fn process(x: string) string { return x; }
    ;

    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    const signatures = sema.overload_groups.get("process").?;
    try std.testing.expect(signatures.len == 3);
}

// ========== 2. Types Equal Test ==========

test "sema_types_equal_i32" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn dummy() {}";
    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    try std.testing.expect(sema.typesEqual(.i32, .i32));
    try std.testing.expect(!sema.typesEqual(.i32, .f64));
}

test "sema_types_equal_f64" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn dummy() {}";
    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    try std.testing.expect(sema.typesEqual(.f64, .f64));
    try std.testing.expect(!sema.typesEqual(.f64, .string));
}

test "sema_types_equal_string" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn dummy() {}";
    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    try std.testing.expect(sema.typesEqual(.string, .string));
    try std.testing.expect(!sema.typesEqual(.string, .i32));
}

// ========== 3. Implicit Conversion Tests ==========

test "sema_can_convert_i32_to_f64" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn dummy() {}";
    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    try std.testing.expect(sema.canImplicitlyConvert(.i32, .f64));
}

test "sema_can_convert_bool_to_i32" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn dummy() {}";
    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    try std.testing.expect(sema.canImplicitlyConvert(.boolean, .i32));
}

test "sema_cannot_convert_string_to_i32" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn dummy() {}";
    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    try std.testing.expect(!sema.canImplicitlyConvert(.string, .i32));
}

// ========== 4. Cache Key Generation ==========

test "sema_overload_cache_key_generation" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn dummy() {}";
    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    const key1 = try sema.makeOverloadCacheKey("max", &[_]AirType{ .i32, .i32 });
    const key2 = try sema.makeOverloadCacheKey("max", &[_]AirType{ .f64, .f64 });

    try std.testing.expect(!std.mem.eql(u8, key1, key2));
    try std.testing.expect(std.mem.startsWith(u8, key1, "max:"));
}

// ========== 5. Multiple Overload Groups ==========

test "sema_multiple_overload_groups" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn max(a: i32, b: i32) i32 { return a; }
        \\fn max(a: f64, b: f64) f64 { return a; }
        \\fn min(a: i32, b: i32) i32 { return a; }
        \\fn min(a: f64, b: f64) f64 { return a; }
    ;

    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    try std.testing.expect(sema.overload_groups.contains("max"));
    try std.testing.expect(sema.overload_groups.contains("min"));

    const max_sigs = sema.overload_groups.get("max").?;
    const min_sigs = sema.overload_groups.get("min").?;

    try std.testing.expect(max_sigs.len == 2);
    try std.testing.expect(min_sigs.len == 2);
}

// ========== 6. Overload with Different Parameter Counts ==========

test "sema_overload_different_param_counts" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn sum() i32 { return 0; }
        \\fn sum(a: i32) i32 { return a; }
        \\fn sum(a: i32, b: i32) i32 { return a + b; }
    ;

    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    const signatures = sema.overload_groups.get("sum").?;
    try std.testing.expect(signatures.len == 3);
}

// ========== 7. Overload with Void Return ==========

test "sema_overload_void_return" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn print(msg: string) { }
        \\fn print(num: i32) { }
    ;

    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    const signatures = sema.overload_groups.get("print").?;
    try std.testing.expect(signatures.len == 2);
}

// ========== 8. Large Overload Group ==========

test "sema_large_overload_group" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn convert(x: i32) f64 { return 0.0; }
        \\fn convert(x: f64) i32 { return 0; }
        \\fn convert(x: string) i32 { return 0; }
        \\fn convert(x: bool) f64 { return 0.0; }
        \\fn convert(x: i64) f64 { return 0.0; }
    ;

    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    const signatures = sema.overload_groups.get("convert").?;
    try std.testing.expect(signatures.len == 5);
}

// ========== 9. Overload with Mixed Names ==========

test "sema_overload_mixed_function_names" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source =
        \\fn add(a: i32, b: i32) i32 { return a + b; }
        \\fn subtract(a: i32, b: i32) i32 { return a - b; }
        \\fn add(a: f64, b: f64) f64 { return a + b; }
        \\fn multiply(a: i32, b: i32) i32 { return a * b; }
    ;

    const sema = try compileToSema(source, allocator);
    defer sema.deinit();

    // "add" 오버로드 그룹: 2개
    const add_sigs = sema.overload_groups.get("add").?;
    try std.testing.expect(add_sigs.len == 2);

    // "subtract", "multiply"는 단일 함수 (오버로드 그룹이 아님)
    try std.testing.expect(!sema.overload_groups.contains("subtract"));
    try std.testing.expect(!sema.overload_groups.contains("multiply"));
}

