const std = @import("std");

pub const Location = struct {
    line: usize,
    column: usize,
    start: usize,
    end: usize,
};

pub const Token = struct {
    tag: Tag,
    loc: Location,

    pub const Tag = enum {
        // Keywords
        fn_,
        const_,
        var_,
        if_,
        else_,
        while_,
        for_,
