const std = @import("std");

pub const Location = struct {
    line: usize,
    column: usize,
    start: usize,
    end: usize,
};

pub const Token = struct {
    tag: Tag,
    loc: Location,

    pub const Tag = enum {
        // Keywords
        fn_,
        const_,
        var_,
        if_,
        else_,
        while_,
        for_,
        return_,
        struct_,
        enum_,
        union_,
        error_,
        try_,
        catch_,
        pub_,
        inline_,
        comptime_,

        // Literals
        integer,
        float,
        string,
        char_literal,
        true_,
        false_,
        null_,

        // Identifiers & types
        identifier,

        // Operators
        plus,          // +
        minus,         // -
        star,          // *
        slash,         // /
        percent,       // %
        equal,         // =
        equal_equal,   // ==
        bang,          // !
        bang_equal,    // !=
        less,          // <
        less_equal,    // <=
        greater,       // >
        greater_equal, // >=
        ampersand,     // &
        pipe,          // |
        caret,         // ^
        tilde,         // ~
        lshift,        // <<
        rshift,        // >>
        and_,          // and
        or_,           // or
        not_,          // not
        dot,           // .
        dot_dot,       // ..
        arrow,         // =>
        question,      // ?
        colon,         // :
        double_colon,  // ::

        // Delimiters
        lparen,        // (
        rparen,        // )
        lbrace,        // {
        rbrace,        // }
        lbracket,      // [
        rbracket,      // ]
        semicolon,     // ;
        comma,         // ,

        // Special
        eof,
        invalid,
    };

    pub fn lexeme(self: Token, source: []const u8) []const u8 {
        return source[self.loc.start..self.loc.end];
    }
};

