현재 로직:
```zig
// 배열 인덱싱
if (self.match(.lbracket)) {
    const index = try self.parseExpression();
    const idx_ptr = try self.allocator.create(Node);
    idx_ptr.* = index;

    self.consume(.rbracket, "Expected ']' after array index")?;

    // ... index_access 생성
}
```

수정할 로직:
```zig
// 배열 인덱싱 / 슬라이싱
if (self.match(.lbracket)) {
    // 첫 번째 표현식 파싱 (또는 없을 수도)
    var start_expr: ?*Node = null;
    if (!self.check(.dot_dot) and !self.check(.rbracket)) {
        const start = try self.parseExpression();
        start_expr = try self.allocator.create(Node);
        start_expr.?.* = start;
    }

    // .. 확인 (슬라이싱)
    if (self.match(.dot_dot)) {
        // 슬라이싱
        var end_expr: ?*Node = null;
        if (!self.check(.rbracket)) {
            const end = try self.parseExpression();
            end_expr = try self.allocator.create(Node);
            end_expr.?.* = end;
        }

        self.consume(.rbracket, "Expected ']' after slice")?;

        const array = try self.allocator.create(Node);
        array.* = expr;

        expr = .{
            .tag = .slice_access,
            .loc = expr.loc,
            .data = .{
                .slice_access = .{
                    .array = array,
                    .start = start_expr,
                    .end = end_expr,
                },
            },
        };
    } else {
        // 인덱싱
        self.consume(.rbracket, "Expected ']' after array index")?;

        const array = try self.allocator.create(Node);
        array.* = expr;

        expr = .{
            .tag = .index_access,
            .loc = expr.loc,
            .data = .{
                .index_access = .{
                    .array = array,
                    .index = start_expr.?,
                },
            },
        };
    }
}
```

슬라이싱 문법을 지원하기 위해 `..` 토큰 확인 후 start와 end 표현식을 선택적으로 파싱한다. 슬라이싱인 경우 slice_access 노드를 생성하고, 단순 인덱싱이면 기존처럼 index_access 노드를 만든다.

