   123→
   124→    /// 함수 선언 생성
   125→    fn genFnDecl(self: *AstGen, node: *const Node) !Zir.Ref {
   126→        const fn_decl = node.data.fn_decl;
   127→        return try self.genFnDeclBase(fn_decl);
   128→    }
   129→
   130→    /// 상수 선언 생성
   131→    fn genConstDecl(self: *AstGen, node: *const Node) !Zir.Ref {
   132→        const const_decl = node.data.const_decl;
   133→
   134→        // 값 생성
   135→        const value_ref = try self.genNode(const_decl.value);
   136→
   137→        // 변수 이름 추가
   138→        const name_index = try self.zir.addString(const_decl.name);
   139→
   140→        // store 명령어 생성
   141→        return try self.zir.addInstruction(.{
   142→            .store_var = .{
   143→                .name_index = name_index,
   144→                .value = value_ref,
   145→            },
   146→        });
   147→    }
   148→
   149→    /// 변수 선언 생성
   150→    fn genVarDecl(self: *AstGen, node: *const Node) !Zir.Ref {
   151→        const var_decl = node.data.var_decl;
   152→
   153→        // 초기값이 있으면 생성
   154→        var value_ref: Zir.Ref = 0;
   155→        if (var_decl.initial_value) |init| {
   156→            value_ref = try self.genNode(init);
   157→        }
   158→
   159→        // 변수 이름 추가
