// 🦎 Phase 3.6: Defer & Resource Management - Parser Tests
// test/phase3_defer_parser_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const Ast = @import("../src/ast.zig");
const Node = Ast.Node;

fn createParser(allocator: std.mem.Allocator, source: []const u8) !Parser {
    var tokenizer = Tokenizer.init(source);
    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (true) {
        const token = tokenizer.nextToken();
        try tokens.append(token);
        if (token.tag == .eof) break;
    }

    return Parser.init(try tokens.toOwnedSlice(), source, allocator);
}

// ============================================================================
// Group A: 기본 defer (2개)
// ============================================================================

test "parser_defer_function_call" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer cleanup(); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    // root → fn_decl → body (block) → expr_stmt (defer_stmt)
    try std.testing.expect(ast.root.tag == .root);
    const fn_node = ast.root.data.block[0];
    try std.testing.expect(fn_node.tag == .fn_decl);

    const body = fn_node.data.fn_decl.body;
    try std.testing.expect(body.tag == .block);
    try std.testing.expect(body.data.block.len >= 1);

    const defer_stmt = body.data.block[0];
    try std.testing.expect(defer_stmt.tag == .defer_stmt);
    try std.testing.expect(defer_stmt.data.defer_stmt.expr.tag == .call);
}

test "parser_defer_method_call" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { defer file.close(); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const defer_stmt = body.data.block[0];

    try std.testing.expect(defer_stmt.tag == .defer_stmt);
    const call_expr = defer_stmt.data.defer_stmt.expr;
    try std.testing.expect(call_expr.tag == .call);
    try std.testing.expect(call_expr.data.call.callee.tag == .member_access);
}

// ============================================================================
// Group B: 다양한 식 (2개)
// ============================================================================

test "parser_defer_member_access" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { defer obj.field; }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const defer_stmt = body.data.block[0];

    try std.testing.expect(defer_stmt.tag == .defer_stmt);
    const expr = defer_stmt.data.defer_stmt.expr;
    try std.testing.expect(expr.tag == .member_access);
}

test "parser_defer_compound_expr" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { defer alloc.free(ptr); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const defer_stmt = body.data.block[0];

    try std.testing.expect(defer_stmt.tag == .defer_stmt);
    const expr = defer_stmt.data.defer_stmt.expr;
    try std.testing.expect(expr.tag == .call);
}

// ============================================================================
// Group C: 블록 내 (3개)
// ============================================================================

test "parser_defer_in_if_block" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { if (x > 0) { defer cleanup(); } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const if_stmt = body.data.block[0];

    try std.testing.expect(if_stmt.tag == .if_stmt);
    const then_block = if_stmt.data.if_stmt.then_branch;
    try std.testing.expect(then_block.tag == .block);
    try std.testing.expect(then_block.data.block.len >= 1);

    const defer_stmt = then_block.data.block[0];
    try std.testing.expect(defer_stmt.tag == .defer_stmt);
}

test "parser_defer_in_while_block" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { while (i < 10) { defer i = i + 1; } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const while_stmt = body.data.block[0];

    try std.testing.expect(while_stmt.tag == .while_stmt);
    const while_body = while_stmt.data.while_stmt.body;
    try std.testing.expect(while_body.tag == .block);

    const defer_stmt = while_body.data.block[0];
    try std.testing.expect(defer_stmt.tag == .defer_stmt);
}

test "parser_defer_multiple_defer" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { defer cleanup1(); defer cleanup2(); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;

    try std.testing.expect(body.data.block.len >= 2);
    try std.testing.expect(body.data.block[0].tag == .defer_stmt);
    try std.testing.expect(body.data.block[1].tag == .defer_stmt);
}

// ============================================================================
// Group D: 함수 (3개)
// ============================================================================

test "parser_defer_in_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process() { var x: i32 = 10; defer print(x); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    try std.testing.expect(fn_node.tag == .fn_decl);

    const body = fn_node.data.fn_decl.body;
    try std.testing.expect(body.data.block.len >= 2);

    // 두 번째 statement는 defer
    const defer_stmt = body.data.block[1];
    try std.testing.expect(defer_stmt.tag == .defer_stmt);
}

test "parser_defer_with_params" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn release(ptr: *i32) { defer print(ptr); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    try std.testing.expect(fn_node.tag == .fn_decl);

    const params = fn_node.data.fn_decl.params;
    try std.testing.expect(params.len >= 1);

    const body = fn_node.data.fn_decl.body;
    const defer_stmt = body.data.block[0];
    try std.testing.expect(defer_stmt.tag == .defer_stmt);
}

test "parser_defer_scope_handling" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { { defer a(); } { defer b(); } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;

    // 두 개의 블록 스코프
    try std.testing.expect(body.data.block.len >= 2);

    const block1 = body.data.block[0];
    const block2 = body.data.block[1];
    try std.testing.expect(block1.tag == .block);
    try std.testing.expect(block2.tag == .block);

    const defer1 = block1.data.block[0];
    const defer2 = block2.data.block[0];
    try std.testing.expect(defer1.tag == .defer_stmt);
    try std.testing.expect(defer2.tag == .defer_stmt);
}

// ============================================================================
// Group E: 복합 (2개)
// ============================================================================

test "parser_nested_defer" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { defer { defer inner(); } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const outer_defer = body.data.block[0];

    try std.testing.expect(outer_defer.tag == .defer_stmt);
    const deferred_block = outer_defer.data.defer_stmt.expr;
    try std.testing.expect(deferred_block.tag == .block);
}

test "parser_defer_with_other_stmts" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { var x: i32 = 5; defer print(x); const y: i32 = 10; }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;

    try std.testing.expect(body.data.block.len >= 3);
    try std.testing.expect(body.data.block[0].tag == .var_decl);
    try std.testing.expect(body.data.block[1].tag == .defer_stmt);
    try std.testing.expect(body.data.block[2].tag == .const_decl);
}

// ============================================================================
// Group F: 에러 (1개)
