    const defer_stmt = body.data.block[0];

    try std.testing.expect(defer_stmt.tag == .defer_stmt);
    const call_expr = defer_stmt.data.defer_stmt.expr;
    try std.testing.expect(call_expr.tag == .call);
    try std.testing.expect(call_expr.data.call.callee.tag == .member_access);
}

