// 🦎 Phase 3.6: Defer & Resource Management - AstGen Tests
// test/phase3_defer_astgen_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const AstGen = @import("../src/astgen.zig").AstGen;
const Ast = @import("../src/ast.zig");
const Zir = @import("../src/zir.zig").Zir;

fn createAstGen(allocator: std.mem.Allocator, source: []const u8) !AstGen {
    var tokenizer = Tokenizer.init(source);
    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (true) {
        const token = tokenizer.nextToken();
        try tokens.append(token);
        if (token.tag == .eof) break;
    }

    var parser = Parser.init(try tokens.toOwnedSlice(), source, allocator);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    var astgen = try AstGen.init(allocator, source);
    try astgen.genProgram(&ast);
    return astgen;
}

// ============================================================================
// Group A: 기본 defer ZIR (2개)
// ============================================================================

test "astgen_defer_function_call_zir" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer cleanup(); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // defer_stmt 명령어 존재 확인
    var found_defer = false;
    for (astgen.zir.instructions.items) |inst| {
        if (inst == .defer_stmt) {
            found_defer = true;
            try std.testing.expect(inst.defer_stmt.scope_id == 0);
            try std.testing.expect(inst.defer_stmt.defer_index == 0);
            break;
        }
    }
    try std.testing.expect(found_defer);
}

test "astgen_defer_method_call_zir" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { defer file.close(); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // defer_stmt 명령어 존재 확인
    var found_defer = false;
    for (astgen.zir.instructions.items) |inst| {
        if (inst == .defer_stmt) {
            found_defer = true;
            try std.testing.expect(inst.defer_stmt.expr != 0);  // 식이 있어야 함
            break;
        }
    }
    try std.testing.expect(found_defer);
}

// ============================================================================
// Group B: 스코프 추적 (3개)
// ============================================================================

test "astgen_defer_scope_tracking" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { { defer cleanup(); } }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // defer 명령어의 scope_id 확인
    var found_defer = false;
    for (astgen.zir.instructions.items) |inst| {
        if (inst == .defer_stmt) {
            found_defer = true;
            // scope_id가 설정되어야 함
            try std.testing.expect(inst.defer_stmt.scope_id >= 0);
            break;
        }
    }
    try std.testing.expect(found_defer);
}

test "astgen_multiple_defers_same_scope" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer cleanup1(); defer cleanup2(); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // 같은 스코프에서 여러 defer의 인덱스 증가 확인
    var defer_count: usize = 0;
    var last_defer_index: u32 = 0;
    for (astgen.zir.instructions.items) |inst| {
        if (inst == .defer_stmt) {
            if (defer_count > 0) {
                // 같은 scope_id에서 defer_index가 증가해야 함
                try std.testing.expect(inst.defer_stmt.defer_index > last_defer_index or inst.defer_stmt.scope_id != astgen.zir.instructions.items[@intCast(defer_count - 1)].defer_stmt.scope_id);
            }
            last_defer_index = inst.defer_stmt.defer_index;
            defer_count += 1;
        }
    }
    try std.testing.expect(defer_count >= 2);
}

test "astgen_nested_scopes_defer" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { { defer a(); } { defer b(); } }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // 중첩된 스코프의 defer 명령어 확인
    var defer_count: usize = 0;
    var scope_ids = std.AutoHashMap(u32, bool).init(allocator);
    defer scope_ids.deinit();

    for (astgen.zir.instructions.items) |inst| {
        if (inst == .defer_stmt) {
            defer_count += 1;
            try scope_ids.put(inst.defer_stmt.scope_id, true);
        }
    }
    try std.testing.expect(defer_count >= 2);
}

// ============================================================================
// Group C: 메타데이터 (2개)
// ============================================================================

test "astgen_defer_index_generation" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer a(); defer b(); defer c(); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // defer 인덱스가 순차적으로 증가하는지 확인
    var indices = std.ArrayList(u32).init(allocator);
    defer indices.deinit();

    for (astgen.zir.instructions.items) |inst| {
        if (inst == .defer_stmt) {
            try indices.append(inst.defer_stmt.defer_index);
        }
    }

    try std.testing.expect(indices.items.len >= 3);
    for (indices.items[1..], 1..) |idx, i| {
        // 같은 스코프라면 인덱스가 증가해야 함
        if (i > 0) {
            try std.testing.expect(idx >= indices.items[i - 1]);
        }
    }
}

test "astgen_defer_count_tracking" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer cleanup1(); defer cleanup2(); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // 현재 스코프의 defer_count 확인
    try std.testing.expect(astgen.current_scope.defer_count >= 2);
}

// ============================================================================
// Group D: 복합 (3개)
// ============================================================================

test "astgen_defer_in_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process() { var x: i32 = 10; defer print(x); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // defer 명령어 존재
    var found_defer = false;
    for (astgen.zir.instructions.items) |inst| {
        if (inst == .defer_stmt) {
            found_defer = true;
            break;
        }
    }
    try std.testing.expect(found_defer);
}

test "astgen_defer_in_block" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { { defer cleanup(); } }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // 블록 내 defer 명령어 확인
    var found_block_begin = false;
    var found_defer = false;

    for (astgen.zir.instructions.items) |inst| {
        if (inst == .block_begin) {
            found_block_begin = true;
        }
        if (inst == .defer_stmt) {
            found_defer = true;
        }
    }
    try std.testing.expect(found_block_begin);
    try std.testing.expect(found_defer);
}

test "astgen_defer_with_other_stmts" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { var x: i32 = 5; defer print(x); const y: i32 = 10; }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // store_var, defer_stmt, store_var 순서 확인
    var store_count: usize = 0;
    var defer_count: usize = 0;

    for (astgen.zir.instructions.items) |inst| {
        if (inst == .store_var) {
            store_count += 1;
        }
        if (inst == .defer_stmt) {
            defer_count += 1;
        }
    }
    try std.testing.expect(store_count >= 2);
    try std.testing.expect(defer_count >= 1);
}

// ============================================================================
// Group E: 엣지 케이스 (2개)
// ============================================================================

test "astgen_multiple_defer_ordering" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer print(\"1\"); defer print(\"2\"); defer print(\"3\"); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // 3개의 defer 명령어와 순서 확인
    var defers = std.ArrayList(u32).init(allocator);
    defer defers.deinit();

    for (astgen.zir.instructions.items) |inst| {
        if (inst == .defer_stmt) {
            try defers.append(inst.defer_stmt.defer_index);
        }
    }

    try std.testing.expect(defers.items.len == 3);
    try std.testing.expect(defers.items[0] == 0);
    try std.testing.expect(defers.items[1] == 1);
    try std.testing.expect(defers.items[2] == 2);
}

test "astgen_defer_chain_generation" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer a(); defer b(); defer c(); defer d(); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    // 4개의 defer 명령어 생성 확인
    var defer_count: usize = 0;
    for (astgen.zir.instructions.items) |inst| {
        if (inst == .defer_stmt) {
            defer_count += 1;
        }
    }
    try std.testing.expect(defer_count == 4);
}

