     1→// 🦎 Mini Zig Compiler - Phase 2.4: AIR
     2→// src/air.zig: Analyzed Intermediate Representation (with Type Information)
     3→
     4→const std = @import("std");
     5→
     6→/// Type System
     7→pub const Type = union(enum) {
     8→    void,
     9→    i32,
    10→    i64,
    11→    f32,
    12→    f64,
    13→    bool,
    14→    string,
    15→    array: struct {
    16→        element_ty: *Type,
    17→        len: ?usize,
    18→    },
    19→    slice: struct {
    20→        element_ty: *Type,
    21→        is_const: bool = false,
    22→    },
    23→    function: struct {
    24→        params: []Type,
    25→        return_ty: *Type,
    26→    },
    27→    unknown, // 아직 추론되지 않음
    28→};
    29→
    30→/// AIR Instruction (with Type Information)
    31→pub const Instruction = union(enum) {
    32→    // 리터럴 (타입 정보 포함)
    33→    load_int: struct { value: i64, ty: Type },
    34→    load_float: struct { value: f64, ty: Type },
    35→    load_string: struct { index: u32, ty: Type },
    36→
    37→    // 변수 (타입 정보 포함)
    38→    load_var: struct { name_index: u32, ty: Type },
    39→    store_var: struct { name_index: u32, value: Ref, ty: Type },
    40→
    41→    // 연산자 (연산 결과 타입 포함)
    42→    binary_op: struct { op: BinaryOp, lhs: Ref, rhs: Ref, result_ty: Type },
    43→    unary_op: struct { op: UnaryOp, operand: Ref, result_ty: Type },
    44→
    45→    // 함수
    46→    fn_begin: struct { name_index: u32, params: []Ref, return_ty: Type },
    47→    fn_end,
    48→
    49→    // 제어 흐름
    50→    call: struct { callee: Ref, args: []Ref, return_ty: Type },
    51→    br: Ref,
    52→    cond_br: struct { cond: Ref, then_block: Ref, else_block: ?Ref },
    53→    return_val: ?Ref,
    54→
    55→    // 블록
    56→    block_begin: struct { label: u32 },
    57→    block_end,
    58→
    59→    // 배열/메모리
    60→    array_literal: struct { elements: []Ref, element_ty: Type },
    61→    index_access: struct { array: Ref, index: Ref, element_ty: Type },
    62→    member_access: struct { object: Ref, field_index: u32, field_ty: Type },
    63→
    64→    // 제어 흐름 (advanced)
    65→    loop_begin: struct { label: u32 },
    66→    loop_end,
    67→    break_loop: struct { label: u32 },
    68→    continue_loop: struct { label: u32 },
    69→
    70→    // 기타
    71→    noop,
    72→};
    73→
    74→pub const Ref = u32; // Instruction 인덱스
    75→
    76→pub const BinaryOp = enum {
    77→    add, sub, mul, div, mod,
    78→    eq, ne, lt, le, gt, ge,
    79→    logical_and, logical_or,
    80→    bitwise_and, bitwise_or, bitwise_xor,
    81→    lshift, rshift,
    82→};
    83→
    84→pub const UnaryOp = enum {
    85→    negate, not, bitwise_not,
    86→};
    87→
    88→/// AIR - Analyzed Intermediate Representation
    89→pub const Air = struct {
    90→    instructions: std.ArrayList(Instruction),
    91→    extra: std.ArrayList(u32),
    92→    strings: std.StringHashMap([]const u8),
    93→    allocator: std.mem.Allocator,
    94→
    95→    pub fn init(allocator: std.mem.Allocator) Air {
    96→        return .{
    97→            .instructions = std.ArrayList(Instruction).init(allocator),
    98→            .extra = std.ArrayList(u32).init(allocator),
    99→            .strings = std.StringHashMap([]const u8).init(allocator),
   100→            .allocator = allocator,
   101→        };
   102→    }
   103→
   104→    pub fn deinit(self: *Air) void {
   105→        self.instructions.deinit();
   106→        self.extra.deinit();
   107→        self.strings.deinit();
   108→    }
   109→
   110→    /// 명령어 추가 및 Ref 반환
   111→    pub fn addInstruction(self: *Air, inst: Instruction) !Ref {
   112→        const index: Ref = @intCast(self.instructions.items.len);
   113→        try self.instructions.append(inst);
   114→        return index;
   115→    }
   116→
   117→    /// 문자열 추가 및 인덱스 반환
   118→    pub fn addString(self: *Air, text: []const u8) !u32 {
   119→        if (self.strings.get(text)) |_| {
   120→            return @intCast(self.strings.count() - 1);
   121→        }
   122→
   123→        const index: u32 = @intCast(self.strings.count());
   124→        try self.strings.put(text, text);
   125→        return index;
   126→    }
   127→
   128→    /// 추가 데이터 저장소에 값 추가
   129→    pub fn addExtra(self: *Air, value: u32) !u32 {
   130→        const index: u32 = @intCast(self.extra.items.len);
   131→        try self.extra.append(value);
   132→        return index;
   133→    }
   134→};
   135→
   136→/// Type 유틸리티 함수들
   137→pub fn typeEq(t1: Type, t2: Type) bool {
   138→    switch (t1) {
   139→        .void => return t2 == .void,
   140→        .i32 => return t2 == .i32,
   141→        .i64 => return t2 == .i64,
   142→        .f32 => return t2 == .f32,
   143→        .f64 => return t2 == .f64,
   144→        .bool => return t2 == .bool,
   145→        .string => return t2 == .string,
   146→        .unknown => return t2 == .unknown,
   147→        .array => |arr1| {
   148→            if (t2 == .array) {
   149→                const arr2 = t2.array;
   150→                return typeEq(arr1.element_ty.*, arr2.element_ty.*) and
   151→                    arr1.len == arr2.len;
   152→            }
   153→            return false;
   154→        },
   155→        .function => {
   156→            // 함수 타입 비교는 복잡하므로 나중에 구현
   157→            return false;
   158→        },
   159→    }
   160→}
   161→
   162→pub fn typeName(t: Type) []const u8 {
   163→    return switch (t) {
   164→        .void => "void",
   165→        .i32 => "i32",
   166→        .i64 => "i64",
   167→        .f32 => "f32",
   168→        .f64 => "f64",
   169→        .bool => "bool",
   170→        .string => "string",
   171→        .unknown => "unknown",
   172→        .array => "array",
   173→        .function => "function",
   174→    };
   175→}
   176→
   177→/// AIR 디버깅용 출력 함수
   178→pub fn printAir(air: *const Air, indent: usize) void {
   179→    const spaces = " " ** indent;
   180→    const stdout = std.io.getStdOut().writer();
   181→
   182→    stdout.print("{s}=== AIR Instructions ===\n", .{spaces}) catch {};
   183→
   184→    for (air.instructions.items, 0..) |inst, idx| {
   185→        stdout.print("{s}[{}] ", .{ spaces, idx }) catch {};
   186→
   187→        switch (inst) {
   188→            .load_int => |data| {
   189→                stdout.print("load_int {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   190→            },
   191→            .load_float => |data| {
   192→                stdout.print("load_float {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   193→            },
   194→            .load_string => |data| {
   195→                stdout.print("load_string @{} ({s})\n", .{ data.index, typeName(data.ty) }) catch {};
   196→            },
   197→            .load_var => |data| {
   198→                stdout.print("load_var @{} ({s})\n", .{ data.name_index, typeName(data.ty) }) catch {};
   199→            },
   200→            .store_var => |data| {
   201→                stdout.print("store_var @{} = %{} ({s})\n", .{ data.name_index, data.value, typeName(data.ty) }) catch {};
   202→            },
   203→            .binary_op => |data| {
   204→                stdout.print("binary_op {:s} %{} %{} → {s}\n", .{ @tagName(data.op), data.lhs, data.rhs, typeName(data.result_ty) }) catch {};
   205→            },
   206→            .unary_op => |data| {
   207→                stdout.print("unary_op {:s} %{} → {s}\n", .{ @tagName(data.op), data.operand, typeName(data.result_ty) }) catch {};
   208→            },
   209→            .fn_begin => |data| {
   210→                stdout.print("fn_begin @{} (params: {}, return: {s})\n", .{ data.name_index, data.params.len, typeName(data.return_ty) }) catch {};
   211→            },
   212→            .fn_end => {
   213→                stdout.print("fn_end\n", .{}) catch {};
   214→            },
   215→            .call => |data| {
   216→                stdout.print("call %{} (args: {}, return: {s})\n", .{ data.callee, data.args.len, typeName(data.return_ty) }) catch {};
   217→            },
   218→            .return_val => |ret| {
   219→                if (ret) |r| {
   220→                    stdout.print("return %{}\n", .{r}) catch {};
   221→                } else {
   222→                    stdout.print("return void\n", .{}) catch {};
   223→                }
   224→            },
   225→            .block_begin => |data| {
   226→                stdout.print("block_begin @{}\n", .{data.label}) catch {};
   227→            },
   228→            .block_end => {
   229→                stdout.print("block_end\n", .{}) catch {};
   230→            },
   231→            .array_literal => |data| {
   232→                stdout.print("array_literal (elements: {}, type: {s})\n", .{ data.elements.len, typeName(data.element_ty) }) catch {};
   233→            },
   234→            .noop => {
   235→                stdout.print("noop\n", .{}) catch {};
   236→            },
   237→            else => {
   238→                stdout.print("{s}\n", .{@tagName(inst)}) catch {};
   239→            },
   240→        }
   241→    }
   242→
   243→    stdout.print("{s}=== Strings ===\n", .{spaces}) catch {};
   244→    var iter = air.strings.iterator();
   245→    var idx: u32 = 0;
   246→    while (iter.next()) |entry| {
   247→        stdout.print("{s}@{}: \"{s}\"\n", .{ spaces, idx, entry.value_ptr.* }) catch {};
   248→        idx += 1;
   249→    }
   250→}
