// 🦎 Phase 3.6: Defer & Resource Management - Sema Tests
// test/phase3_defer_sema_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const AstGen = @import("../src/astgen.zig").AstGen;
const Sema = @import("../src/sema.zig").Sema;
const Air = @import("../src/air.zig").Air;
const AirType = @import("../src/air.zig").Type;
const Ast = @import("../src/ast.zig");

fn createSema(allocator: std.mem.Allocator, source: []const u8) !Sema {
    var tokenizer = Tokenizer.init(source);
    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (true) {
        const token = tokenizer.nextToken();
        try tokens.append(token);
        if (token.tag == .eof) break;
    }

    var parser = Parser.init(try tokens.toOwnedSlice(), source, allocator);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    var astgen = try AstGen.init(allocator, source);
    defer astgen.deinit();
    try astgen.genProgram(&ast);

    const air = try allocator.create(Air);
    air.* = Air.init(allocator);

    return .{
        .zir = astgen.zir,
        .air = air,
        .allocator = allocator,
    };
}

// ============================================================================
// Group A: 타입 검증 (2개)
// ============================================================================

test "sema_defer_void_type" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer cleanup(); }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // void 타입 검증
    const void_ty: AirType = .void;
    const result = try sema.checkDeferStmt(void_ty);
    try std.testing.expect(result == .void);
}

test "sema_defer_non_void_error" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer x = 5; }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // i32 타입은 에러여야 함
    const i32_ty: AirType = .i32;
    const result = sema.checkDeferStmt(i32_ty);
    try std.testing.expectError(error.DeferExprNotVoid, result);
}

// ============================================================================
// Group B: 함수 호출 (3개)
// ============================================================================

test "sema_defer_function_call_type" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn cleanup() {} fn main() { defer cleanup(); }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // 함수 호출의 반환 타입이 void
    const fn_return_ty: AirType = .void;
    const result = try sema.checkDeferStmt(fn_return_ty);
    try std.testing.expect(result == .void);
}

test "sema_defer_method_call_type" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer file.close(); }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // 메서드 호출의 반환 타입이 void
    const method_return_ty: AirType = .void;
    const result = try sema.checkDeferStmt(method_return_ty);
    try std.testing.expect(result == .void);
}

test "sema_defer_invalid_call" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn getValue(): i32 { return 5; } fn main() { defer getValue(); }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // i32를 반환하는 함수는 에러
    const fn_return_ty: AirType = .i32;
    const result = sema.checkDeferStmt(fn_return_ty);
    try std.testing.expectError(error.DeferExprNotVoid, result);
}

// ============================================================================
// Group C: 스코프 (3개)
// ============================================================================

test "sema_defer_scope_tracking" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer cleanup(); }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // 스코프 추적 호출 (검증만)
    try sema.trackDeferScope(0);
}

test "sema_nested_defer_scopes" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { { defer a(); } { defer b(); } }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // 여러 스코프 추적
    try sema.trackDeferScope(0);
    try sema.trackDeferScope(1);
    try sema.trackDeferScope(2);
}

test "sema_defer_multiple_same_scope" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer a(); defer b(); defer c(); }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // 같은 스코프 내 여러 defer
    try sema.trackDeferScope(0);
}

// ============================================================================
// Group D: 순서 (2개)
// ============================================================================

test "sema_defer_lifo_order" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer print(\"1\"); defer print(\"2\"); defer print(\"3\"); }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // defer 순서 검증 (3개는 LIFO 순서로 실행)
    var defers = std.ArrayList(Sema.DeferInfo).init(allocator);
    defer defers.deinit();

    try defers.append(.{
        .expr_ty = .void,
        .scope_id = 0,
        .defer_index = 0,
        .location = .{ .line = 1, .column = 1, .start = 0, .end = 1 },
    });
    try defers.append(.{
        .expr_ty = .void,
        .scope_id = 0,
        .defer_index = 1,
        .location = .{ .line = 1, .column = 1, .start = 0, .end = 1 },
    });
    try defers.append(.{
        .expr_ty = .void,
        .scope_id = 0,
        .defer_index = 2,
        .location = .{ .line = 1, .column = 1, .start = 0, .end = 1 },
    });

    // LIFO 검증
    try sema.validateDeferOrdering(defers.items);
}

test "sema_defer_execution_order" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { defer cleanup1(); defer cleanup2(); }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

    // 실행 순서: cleanup2 (index 1) → cleanup1 (index 0)
    var defers = std.ArrayList(Sema.DeferInfo).init(allocator);
    defer defers.deinit();

    try defers.append(.{
        .expr_ty = .void,
        .scope_id = 0,
        .defer_index = 0,
        .location = .{ .line = 1, .column = 1, .start = 0, .end = 1 },
    });
    try defers.append(.{
        .expr_ty = .void,
        .scope_id = 0,
        .defer_index = 1,
        .location = .{ .line = 1, .column = 1, .start = 0, .end = 1 },
    });

    try sema.validateDeferOrdering(defers.items);
}

// ============================================================================
// Group E: 복합 (3개)
// ============================================================================

test "sema_defer_in_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process() { var x: i32 = 10; defer print(x); }";
    var sema = try createSema(allocator, source);
    defer sema.air.deinit();

