// 🦎 Phase 3.7: Error Handling - Parser Tests
// test/phase3_error_parser_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const Ast = @import("../src/ast.zig");
const Node = Ast.Node;

fn createParser(allocator: std.mem.Allocator, source: []const u8) !Parser {
    var tokenizer = Tokenizer.init(source);
    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (true) {
        const token = tokenizer.nextToken();
        try tokens.append(token);
        if (token.tag == .eof) break;
    }

    return Parser.init(try tokens.toOwnedSlice(), source, allocator);
}

// ============================================================================
// Group A: 기본 try (2개)
// ============================================================================

test "parser_try_simple_expr" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try getValue(); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
    const fn_node = ast.root.data.block[0];
    try std.testing.expect(fn_node.tag == .fn_decl);

    const body = fn_node.data.fn_decl.body;
    try std.testing.expect(body.tag == .block);
    try std.testing.expect(body.data.block.len >= 1);

    const try_stmt = body.data.block[0];
    try std.testing.expect(try_stmt.tag == .try_expr);
    try std.testing.expect(try_stmt.data.try_expr_data.expr.tag == .call);
}

test "parser_try_function_call" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { try openFile(\"data.txt\"); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const try_stmt = body.data.block[0];

    try std.testing.expect(try_stmt.tag == .try_expr);
    const call_expr = try_stmt.data.try_expr_data.expr;
    try std.testing.expect(call_expr.tag == .call);
}

// ============================================================================
// Group B: Try-Catch (2개)
// ============================================================================

test "parser_try_catch_basic" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try getValue() catch |err| { print(err); } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const catch_stmt = body.data.block[0];

    try std.testing.expect(catch_stmt.tag == .catch_expr);
    try std.testing.expect(std.mem.eql(u8, catch_stmt.data.catch_expr_data.error_name, "err"));
}

test "parser_try_catch_with_body" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try openFile(\"data.txt\") catch |e| { print(\"Error: \"); print(e); } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const catch_stmt = body.data.block[0];

    try std.testing.expect(catch_stmt.tag == .catch_expr);
    const catch_body = catch_stmt.data.catch_expr_data.body;
    try std.testing.expect(catch_body.tag == .block);
}

// ============================================================================
// Group C: 에러 타입 (2개)
// ============================================================================

test "parser_error_type_definition" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const FileError = error { NotFound, PermissionDenied };";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
}

test "parser_error_union_type" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn readFile(): ![]u8 { try openFile(...); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
}

// ============================================================================
// Group D: 에러 전파 (2개)
// ============================================================================

test "parser_error_propagation" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process() { const data = try readFile(); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;

    try std.testing.expect(body.data.block.len >= 1);
    const const_stmt = body.data.block[0];
    try std.testing.expect(const_stmt.tag == .const_decl);
}

test "parser_multiple_try" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try a(); try b(); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;

    try std.testing.expect(body.data.block.len >= 2);
    try std.testing.expect(body.data.block[0].tag == .try_expr);
    try std.testing.expect(body.data.block[1].tag == .try_expr);
}

// ============================================================================
// Group E: 복합 (3개)
// ============================================================================

test "parser_nested_try_catch" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try (try inner()) catch |e| { print(e); } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const catch_stmt = body.data.block[0];

    try std.testing.expect(catch_stmt.tag == .catch_expr);
}

test "parser_try_in_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process() { var x: []u8 = try alloc.alloc(100); defer alloc.free(x); }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    try std.testing.expect(fn_node.tag == .fn_decl);

    const body = fn_node.data.fn_decl.body;
    try std.testing.expect(body.data.block.len >= 2);
}

test "parser_try_with_other_stmts" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { const x: i32 = 5; try process(x); const y: i32 = 10; }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;

    try std.testing.expect(body.data.block.len >= 3);
    try std.testing.expect(body.data.block[0].tag == .const_decl);
    try std.testing.expect(body.data.block[1].tag == .try_expr);
    try std.testing.expect(body.data.block[2].tag == .const_decl);
}

// ============================================================================
// Group F: 엣지 케이스 (2개)
// ============================================================================

test "parser_try_chain" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
