   145→    /// 함수 선언 생성
   146→    fn genFnDecl(self: *AstGen, node: *const Node) !Zir.Ref {
   147→        const fn_decl = node.data.fn_decl;
   148→        return try self.genFnDeclBase(fn_decl);
   149→    }
   150→
   151→    /// 상수 선언 생성
   152→    fn genConstDecl(self: *AstGen, node: *const Node) !Zir.Ref {
   153→        const const_decl = node.data.const_decl;
   154→
   155→        // 값 생성
   156→        const value_ref = try self.genNode(const_decl.value);
