// 🦎 Phase 3.7: Error Handling - AstGen Tests
// test/phase3_error_astgen_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const Ast = @import("../src/ast.zig");
const AstGen = @import("../src/astgen.zig").AstGen;
const Zir = @import("../src/zir.zig").Zir;

fn createAstGen(allocator: std.mem.Allocator, source: []const u8) !AstGen {
    var tokenizer = Tokenizer.init(source);
    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (true) {
        const token = tokenizer.nextToken();
        try tokens.append(token);
        if (token.tag == .eof) break;
    }

    var parser = try Parser.init(try tokens.toOwnedSlice(), source, allocator);
    const ast = try parser.parseProgram();
    defer ast.deinit();

    var astgen = try AstGen.init(allocator, source);
    try astgen.genProgram(&ast);

    return astgen;
}

// ============================================================================
// Group A: 기본 try ZIR (2개)
// ============================================================================

test "astgen_try_simple_zir" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try getValue(); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // try_expr 명령어가 생성되어야 함
}

test "astgen_try_function_call_zir" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { try openFile(\"data.txt\"); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
}

// ============================================================================
// Group B: Try-Catch ZIR (3개)
// ============================================================================

test "astgen_try_catch_zir" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try getValue() catch |err| { print(err); } }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // catch_expr 명령어가 생성되어야 함
}

test "astgen_catch_body_generation" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try openFile(\"file.txt\") catch |e| { print(\"Error: \"); print(e); } }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
}

test "astgen_error_variable_tracking" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try getValue() catch |error_val| { print(error_val); } }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // 에러 변수명 "error_val"이 string pool에 저장되어야 함
}

// ============================================================================
// Group C: 에러 타입 (2개)
// ============================================================================

test "astgen_error_type_generation" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const FileError = error { NotFound, PermissionDenied };";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // error_type 명령어가 생성되어야 함
}

test "astgen_error_union_type" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn readFile(): ![]u8 { try openFile(...); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // error_union 명령어가 생성되어야 함
}

// ============================================================================
// Group D: 메타데이터 (2개)
// ============================================================================

test "astgen_error_field_tracking" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const MyError = error { IOError, TimeoutError, ParseError };";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // 3개의 에러 필드가 추적되어야 함
}

test "astgen_error_count_metadata" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const NetworkError = error { Unreachable, Timeout, Refused };";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // error_type 명령어의 error_count가 3이어야 함
}

// ============================================================================
// Group E: 복합 (3개)
// ============================================================================

test "astgen_try_in_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process() { var x: []u8 = try alloc.alloc(100); defer alloc.free(x); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // fn_begin, try_expr, defer_stmt 등이 생성되어야 함
}

test "astgen_nested_try_catch" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try (try inner()) catch |e| { print(e); } }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // 중첩된 try_expr과 catch_expr이 생성되어야 함
}

test "astgen_multiple_error_types" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn readData(): ![]u8 { const file = try openFile(\"data.txt\"); defer file.close(); }";
    var astgen = try createAstGen(allocator, source);
    defer astgen.deinit();

    try std.testing.expect(astgen.zir.instructions.items.len > 0);
    // error_union과 defer_stmt가 함께 생성되어야 함
}

