// 🦎 Phase 3.7: Error Handling - Sema Tests
// test/phase3_error_sema_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const Ast = @import("../src/ast.zig");
const AstGen = @import("../src/astgen.zig").AstGen;
const Sema = @import("../src/sema.zig").Sema;

fn createSema(allocator: std.mem.Allocator, source: []const u8) !Sema {
    var tokenizer = Tokenizer.init(source);
    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (true) {
        const token = tokenizer.nextToken();
        try tokens.append(token);
        if (token.tag == .eof) break;
    }

    var parser = try Parser.init(try tokens.toOwnedSlice(), source, allocator);
    const ast = try parser.parseProgram();
    defer ast.deinit();

    var astgen = try AstGen.init(allocator, source);
    try astgen.genProgram(&ast);
    defer astgen.deinit();

    return try Sema.init(allocator, astgen.zir);
}

// ============================================================================
// Group A: Try 타입 검증 (2개)
// ============================================================================

test "sema_try_type_inference" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn getValue() -> i32 { 42 } fn main() { try getValue(); }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // try getValue()는 i32 타입 반환
}

test "sema_try_with_error_union" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn getFile(): ![]u8 { try openFile(\"data.txt\"); }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // try getFile()는 []u8 타입 반환
}

// ============================================================================
// Group B: Catch 검증 (3개)
// ============================================================================

test "sema_catch_error_type" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try getValue() catch |err| { print(err); } }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // catch 블록의 err 변수는 에러 타입
}

test "sema_catch_error_variable" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try openFile(\"file.txt\") catch |error_val| { print(error_val); } }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // error_val은 에러 타입이어야 함
}

test "sema_catch_on_non_error" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn getValue() -> i32 { 42 } fn main() { try getValue() catch |e| { } }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // getValue()는 에러를 반환하지 않으므로 catch 불가능 (에러)
}

// ============================================================================
// Group C: 에러 타입 (2개)
// ============================================================================

test "sema_error_type_definition" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const FileError = error { NotFound, PermissionDenied };";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // FileError는 2개의 에러 필드를 가짐
}

test "sema_error_union_type" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn readFile(): ![]u8 { const file = try openFile(\"data.txt\"); defer file.close(); }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // ![]u8는 error_union 타입 (기본 에러와 []u8)
}

// ============================================================================
// Group D: 타입 일관성 (3개)
// ============================================================================

test "sema_error_propagation" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process() { const data = try readFile(); }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // try readFile()의 에러가 process()로 전파됨
}

test "sema_error_type_mismatch" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { const x: i32 = try getValue(); }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // try getValue()가 i32와 호환되는지 확인
}

test "sema_error_compatibility" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const FileError = error { NotFound }; const IOError = error { Timeout }; fn merge() { }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // FileError와 IOError 타입 호환성
}

// ============================================================================
// Group E: 복합 (3개)
// ============================================================================

test "sema_try_catch_in_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try getValue() catch |err| { print(err); } }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // 함수 내 try-catch 타입 검증
}

test "sema_nested_try_catch" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { try (try inner()) catch |e| { print(e); } }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // 중첩된 try-catch의 타입 검증
}

test "sema_error_handling_flow" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process() { const x = try readFile(); try processFile(x); } fn readFile(): ![]u8 { } fn processFile(data: []u8) { }";
    var sema = try createSema(allocator, source);
    defer sema.deinit();

    // 복합적인 에러 처리 흐름의 타입 일관성
}

