// 🦎 Mini Zig Compiler - Phase 2.2: AST Definition
// src/ast.zig: Abstract Syntax Tree 노드 타입 정의

const std = @import("std");
const Token = @import("tokenizer.zig").Token;

/// 모든 AST 노드의 위치 정보
pub const Location = struct {
    line: usize,
    column: usize,
    start: usize,
    end: usize,
};

/// AST 노드 (모든 가능한 AST 노드 타입)
pub const Node = struct {
    tag: Tag,
    loc: Location,
    data: Data,

    pub const Tag = enum {
        // 프로그램
        root,

        // 선언
        fn_decl,
        var_decl,
        const_decl,

        // 문장
        block,
        if_stmt,
        while_stmt,
        for_stmt,
        return_stmt,
        expr_stmt,
        var_assign,
        defer_stmt,           // defer expr; (Phase 3.6)

        // 식 (Expression)
        binary_op,
        unary_op,
        call,
        member_access,
        index_access,
        integer_literal,
        float_literal,
        string_literal,
        identifier,
        grouped_expr,
        array_literal,

        // 타입
        type_primitive,
        type_pointer,
        type_array,
        type_slice,           // []T 슬라이스 타입 (Phase 3.5)
        type_function,
        type_param,           // Generic 타입 파라미터 (T)

        // 식 (배열/슬라이스 연산)
        slice_access,         // arr[i..j] 슬라이싱 (Phase 3.5)

        // Generic 관련
        generic_param,        // comptime 파라미터
        comptime_decl,        // comptime 블록

        // Comptime Programming (Phase 3.3)
        comptime_block_expr,  // comptime { ... } 식
        const_expr,           // const X = VALUE 식

        // Union/Enum (Phase 3.2)
        union_type,           // union Result { ok: T, err: U }
        enum_type,            // enum Animal { dog, cat }
        union_field,          // Union 필드 정의
        enum_field,           // Enum 값 정의

        // Phase 3.8: Pattern Matching
        switch_expr,          // switch expr { case ... }
        case_pattern,         // pattern => value
        tuple_pattern,        // (a, b, c)
        struct_pattern,       // Point { x, y }
        type_pattern,         // Type 패턴
        wildcard_pattern,     // _ 패턴
        variable_pattern,     // 변수 바인딩

        // 기타
        param,
        arg,
    };

    pub const Data = union {
        // root: []Node,
        // fn_decl, var_decl, const_decl, etc.
        // 일단 단순하게 구현, 나중에 확장

        // 이진 연산자
        binary_op: struct {
            op: BinaryOp,
            lhs: *Node,
            rhs: *Node,
        },

        // 단항 연산자
        unary_op: struct {
            op: UnaryOp,
            operand: *Node,
        },

        // 함수 호출
        call: struct {
            callee: *Node,
            args: []Node,
        },

        // 멤버 접근 (obj.field)
        member_access: struct {
            object: *Node,
            field: []const u8,
        },

        // 배열 인덱싱
        index_access: struct {
            array: *Node,
            index: *Node,
        },

        // 리터럴
        integer: i64,
        float: f64,
        string: []const u8,
        identifier: []const u8,

        // 배열 리터럴
        array_literal: []Node,

        // 식 문장
        expr: *Node,

        // 반환 문
        return_expr: ?*Node,

        // 블록 (복수 문장)
        block: []Node,

        // if 문
        if_stmt: struct {
            condition: *Node,
            then_branch: *Node,
            else_branch: ?*Node,
        },

        // while 루프
        while_stmt: struct {
            condition: *Node,
            body: *Node,
        },

        // for 루프
        for_stmt: struct {
            init: ?*Node,
            condition: ?*Node,
            increment: ?*Node,
            body: *Node,
        },

        // 함수 선언
        fn_decl: struct {
            name: []const u8,
            params: []Param,
            return_type: ?*Node,
            body: *Node,
        },

        // 변수 선언
        var_decl: struct {
            name: []const u8,
            type_annotation: ?*Node,
            initial_value: ?*Node,
        },

        // 상수 선언
        const_decl: struct {
            name: []const u8,
            type_annotation: ?*Node,
            value: *Node,
        },

        // 변수 할당
        var_assign: struct {
            target: *Node,
            value: *Node,
        },

        // 타입 노드
        type_name: []const u8,       // i32, f64, etc.
        pointer_type: *Node,          // *i32
        array_type: struct {
            element_type: *Node,
            size: ?*Node,
        },

        // Phase 3.5: 슬라이스 타입
        slice_type: struct {
            element_type: *Node,
            is_const: bool = false,   // []const T
        },

        // Phase 3.5: 슬라이싱 (arr[i..j])
        slice_access: struct {
            array: *Node,
            start: ?*Node,  // null이면 0부터
            end: ?*Node,    // null이면 끝까지
        },

        // Phase 3.6: Defer 문 (defer expr;)
        defer_stmt: struct {
            expr: *Node,  // defer할 식
        },

        // Phase 3.7: Error Handling
        try_expr,         // try expr
        catch_expr,       // catch |err| { ... }
        error_type,       // error Type
        error_union,      // Type!ErrorType

        // Generic 파라미터 (comptime 키워드)
        generic_param: struct {
            is_comptime: bool,
            name: []const u8,
            constraint: ?*Node,  // type, i32, etc.
        },

        // 타입 파라미터 (Generic T)
        type_param_node: []const u8,

        // Comptime 블록
        comptime_block: *Node,

        // Comptime 블록 식 (Phase 3.3) - comptime { ... }를 식으로 사용
        comptime_block_expr_data: struct {
            body: []Node,
        },

        // 상수 식 (Phase 3.3) - const X = VALUE
        const_expr_data: struct {
            name: []const u8,
            type_node: ?*Node = null,  // 타입 명시적 지정 가능
            value: *Node,               // 초기값 (반드시 상수식이어야 함)
        },

        // Union Type (Phase 3.2)
        union_type_data: struct {
            name: []const u8,
            fields: []UnionField,
            is_tagged: bool = false,  // union(enum)
        },

        // Enum Type (Phase 3.2)
        enum_type_data: struct {
            name: []const u8,
            fields: []EnumField,
            is_tagged: bool = false,  // enum with values
        },

        // Phase 3.7: Error Handling
        try_expr_data: struct {
            expr: *Node,  // try할 식
        },

        catch_expr_data: struct {
            try_expr: *Node,
            error_name: []const u8,  // |err|
            body: *Node,             // { ... }
        },

        error_type_data: struct {
            name: []const u8,
            fields: []ErrorField,
        },

        error_union_data: struct {
            base_type: *Node,
            error_type: *Node,
        },

        // 기본값 (사용 안 함)
        none: void,
    };
};

