/// 패턴 파싱
fn parsePattern(self: *Parser) !Node {
    // 와일드카드 패턴 (_)
    if (self.check(.identifier) and std.mem.eql(u8, self.peek().lexeme(self.source), "_")) {
        const token = self.advance();
        return .{
            .tag = .wildcard_pattern,
            .loc = .{
                .line = token.line,
                .column = token.column,
                .start = token.start,
                .end = token.end,
            },
            .data = .{ .none = {} },
        };
    }

    // 튜플 패턴
    if (self.match(.lparen)) {
        return self.parseTuplePattern();
    }

    // 정수/문자열 리터럴 패턴
    return self.parsePrimaryPattern();
}

