// 🦎 Phase 3.8: Pattern Matching - Parser Tests
// test/phase3_pattern_parser_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const Ast = @import("../src/ast.zig");
const Node = Ast.Node;

fn createParser(allocator: std.mem.Allocator, source: []const u8) !Parser {
    var tokenizer = Tokenizer.init(source);
    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (true) {
        const token = tokenizer.nextToken();
        try tokens.append(token);
        if (token.tag == .eof) break;
    }

    return Parser.init(try tokens.toOwnedSlice(), source, allocator);
}

// ============================================================================
// Group A: 기본 switch (2개)
// ============================================================================

test "parser_switch_value_pattern" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { switch (value) { 1 => print(\"one\"), } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
    const fn_node = ast.root.data.block[0];
    try std.testing.expect(fn_node.tag == .fn_decl);

    const body = fn_node.data.fn_decl.body;
    try std.testing.expect(body.tag == .block);
    try std.testing.expect(body.data.block.len >= 1);

    const switch_stmt = body.data.block[0];
    try std.testing.expect(switch_stmt.tag == .switch_expr);
}

test "parser_switch_multiple_cases" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { switch (value) { 1 => print(\"one\"), 2 => print(\"two\"), 3 => print(\"three\"), } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    const fn_node = ast.root.data.block[0];
    const body = fn_node.data.fn_decl.body;
    const switch_stmt = body.data.block[0];

    try std.testing.expect(switch_stmt.tag == .switch_expr);
    try std.testing.expect(switch_stmt.data.switch_expr_data.cases.len >= 3);
}

// ============================================================================
// Group B: 튜플 분해 (3개)
// ============================================================================

test "parser_tuple_pattern" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { switch (tuple) { (1, 2) => print(\"matched\"), } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
}

test "parser_tuple_destructuring" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { switch (tuple) { (a, b) => print(a), } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
}

test "parser_tuple_with_wildcard" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { switch (tuple) { (x, _) => print(x), } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
}

// ============================================================================
// Group C: 구조체 분해 (3개)
// ============================================================================

test "parser_struct_pattern" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { switch (point) { Point { } => print(\"origin\"), } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
}

test "parser_struct_with_fields" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { switch (point) { Point { x: 0, y: 0 } => print(\"zero\"), } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
}

test "parser_struct_field_binding" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { switch (point) { Point { x: x, y: _ } => print(x), } }";
    var parser = try createParser(allocator, source);
    defer parser.deinit();

    const ast = try parser.parseProgram();
    defer ast.deinit();

    try std.testing.expect(ast.root.tag == .root);
}

// ============================================================================
// Group D: 타입 패턴 (2개)
// ============================================================================

test "parser_type_pattern" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
