// ============================================================================
// Group E: 복합 (3개)
// ============================================================================

test "parser_nested_switch" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){}};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { switch (outer) { 1 => switch (inner) { 2 => print(\"nested\"), }, } }";
    var parser = try createParser(allocator, source);
