        .i64 => return t2 == .i64,
        .f32 => return t2 == .f32,
        .f64 => return t2 == .f64,
        .bool => return t2 == .bool,
        .string => return t2 == .string,
        .unknown => return t2 == .unknown,
        .array => |arr1| {
            if (t2 == .array) {
