    /// Phase 3.8: Switch 식 타입 검증
    fn checkSwitchExpr(self: *Sema, expr_ty: AirType) !AirType {
        _ = self;
        _ = expr_ty;

        // Switch 식의 타입은 첫 케이스 값의 타입
