        _ = self;
        _ = expr_ty;
        _ = patterns;

        // 모든 가능한 경우가 처리되는지 검증
        // 와일드카드(_)가 있으면 완벽함 (exhaustive)
        // 그렇지 않으면 도달 불가능한 케이스 확인
    }

    /// Phase 3.8: 패턴 타입 일치 검증
    fn checkPatternMatch(self: *Sema, expr_ty: AirType, pattern_ty: AirType) !bool {
        _ = self;

        // 패턴이 식 타입과 일치하는지 검증
        return switch (expr_ty) {
            .unknown => true,  // 미지정 타입은 패턴 전부 가능
            else => {
                // 정확한 타입 매칭
                const expr_name = self.getTypeName(expr_ty);
                const pattern_name = self.getTypeName(pattern_ty);
                return std.mem.eql(u8, expr_name, pattern_name);
            },
        };
    }

    /// Phase 3.8: 패턴 바인딩 검증
    fn checkPatternBindings(self: *Sema, pattern: AirType) !void {
        _ = self;
        _ = pattern;

        // 패턴에서 바인드된 변수들을 스코프에 추가
        // 이후 본체에서 해당 변수들이 참조 가능해야 함
    }

    /// 타입명 얻기 (디버그용)
    fn getTypeName(self: *Sema, ty: AirType) []const u8 {
        _ = self;

        return switch (ty) {
            .void => "void",
            .i32 => "i32",
            .i64 => "i64",
            .f32 => "f32",
            .f64 => "f64",
            .bool => "bool",
            .string => "string",
            .unknown => "unknown",
            else => "complex",
        };
    }
