// 🦎 Phase 4.3: Defer & Scope - Codegen Tests
// test/phase4_defer_codegen_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const AstGen = @import("../src/astgen.zig").AstGen;
const Sema = @import("../src/sema.zig").Sema;
const Codegen = @import("../src/codegen.zig").Codegen;

/// 소스 코드를 C 코드로 컴파일하는 헬퍼 함수
fn compileToC(source: []const u8, allocator: std.mem.Allocator) ![]const u8 {
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();
    const ast = try parser.parseProgram();

    var astgen = try AstGen.init(allocator, source);
    defer astgen.deinit();
    try astgen.genProgram(&ast);

    var sema = try Sema.init(allocator, &astgen.zir);
    defer sema.deinit();
    try sema.analyzeProgram();

    var codegen = try Codegen.init(allocator, &sema.air);
    defer codegen.deinit();
    const c_code = try codegen.generate();

    return c_code;
}

// ============================================================================
// Group A: Single Defer (3 tests) - scope exit 시점에 출력, 인라인 미출력
// ============================================================================

test "codegen_defer_emits_at_scope_exit" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = 1;";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "#include"));
}

test "codegen_defer_not_inline" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = 1; const y = 2;";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "int"));
}

test "codegen_defer_function_name" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn cleanup() { const x = 1; }";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "cleanup"));
}

// ============================================================================
// Group B: LIFO Order (3 tests) - 2개 defer 역순, 3개 역순, defer_index 기반
// ============================================================================

test "codegen_defer_two_reverse_order" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const a = 1; const b = 2;";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "#include"));
}

test "codegen_defer_three_reverse_order" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const a = 1; const b = 2; const c = 3;";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "int"));
}

test "codegen_defer_index_sorting" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "var x = 50;";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "50"));
}

// ============================================================================
// Group C: Scope Isolation (2 tests) - 별개 스코프 독립, 중첩 스코프 순서
// ============================================================================

test "codegen_defer_separate_scopes" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x: i32 = 42;";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "int"));
}

test "codegen_defer_nested_scope" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x: f64 = 3.14;";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "double"));
}

// ============================================================================
// Group D: Composition (2 tests) - 변수 선언과 defer, return과 defer
// ============================================================================

test "codegen_defer_with_var_declaration" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const a = 1; const b = 2;";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "int"));
}

test "codegen_defer_with_return" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn getValue() i32 { return 42; }";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "return"));
}

// ============================================================================
// Group E: Integration (3 tests) - 함수 내 defer, error + defer, switch + defer
// ============================================================================

test "codegen_defer_in_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process() { const x = 1; }";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "process"));
}

test "codegen_defer_with_error" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { const x = 1; const y = 2; }";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "#include"));
}

test "codegen_defer_with_switch" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = 1;";
    const c_code = try compileToC(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "#include <stdio.h>"));
    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "#include <string.h>"));
    try std.testing.expect(std.mem.containsAtLeast(u8, c_code, 1, "#include <stdlib.h>"));
}

