// 🦎 Phase 5.1: Basic Values & Functions - LLVM IR Tests
// test/phase5_basic_ir_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const AstGen = @import("../src/astgen.zig").AstGen;
const Sema = @import("../src/sema.zig").Sema;
const LLVMIRGen = @import("../src/llvm_ir.zig").LLVMIRGen;

/// 소스 코드를 LLVM IR로 컴파일하는 헬퍼 함수
fn compileToLLVMIR(source: []const u8, allocator: std.mem.Allocator) ![]const u8 {
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();
    const ast = try parser.parseProgram();

    var astgen = try AstGen.init(allocator, source);
    defer astgen.deinit();
    try astgen.genProgram(&ast);

    var sema = try Sema.init(allocator, &astgen.zir);
    defer sema.deinit();
    try sema.analyzeProgram();

    var llvm_ir = try LLVMIRGen.init(allocator, &sema.air);
    defer llvm_ir.deinit();
    const ir_code = try llvm_ir.generate();

    return ir_code;
}

// ============================================================================
// Group A: Literals (3 tests) - i32, f64, string
// ============================================================================

test "llvm_load_int_literal" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = 42;";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "target triple"));
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "42"));
}

test "llvm_load_float_literal" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = 3.14;";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "3.14"));
}

test "llvm_load_string_literal" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = \"hello\";";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "@.str"));
}

// ============================================================================
// Group B: Variables (3 tests) - alloca, store, load
// ============================================================================

test "llvm_var_alloca_store_load" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "var x = 10;";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "alloca"));
}

test "llvm_var_assignment" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "var x = 5; x = 20;";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "store"));
}

test "llvm_const_var" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const y = 15;";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "i32"));
}

// ============================================================================
// Group C: Binary & Unary Ops (2 tests) - add, icmp
// ============================================================================

test "llvm_binary_op_add" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = 2 + 3;";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "add"));
}

test "llvm_binary_op_compare" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = 5 == 5;";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "icmp"));
}

// ============================================================================
// Group D: Functions (2 tests) - define, params
// ============================================================================

test "llvm_function_definition" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn add(a: i32, b: i32) i32 { return a + b; }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "define"));
}

test "llvm_function_params" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test(x: i32, y: i32) i32 { return 0; }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "@test"));
}

// ============================================================================
// Group E: Integration (3 tests) - preamble, body, compound
// ============================================================================

test "llvm_preamble_included" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = 1;";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "target triple"));
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "target datalayout"));
}

test "llvm_function_body" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() { const x = 1; }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "entry:"));
}

test "llvm_compound_expr" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const x = 2 + 3 * 4;";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "add") or std.mem.containsAtLeast(u8, ir_code, 1, "mul"));
}

