// 🦎 Phase 5.2: Control Flow - LLVM IR Tests
// test/phase5_control_flow_ir_test.zig

const std = @import("std");
const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
const Parser = @import("../src/parser.zig").Parser;
const AstGen = @import("../src/astgen.zig").AstGen;
const Sema = @import("../src/sema.zig").Sema;
const LLVMIRGen = @import("../src/llvm_ir.zig").LLVMIRGen;

/// 소스 코드를 LLVM IR로 컴파일하는 헬퍼 함수
fn compileToLLVMIR(source: []const u8, allocator: std.mem.Allocator) ![]const u8 {
    var tokenizer = try Tokenizer.init(source, allocator);
    defer tokenizer.deinit();

    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    defer tokens.deinit();

    while (try tokenizer.nextToken()) |token| {
        try tokens.append(token);
    }

    var parser = try Parser.init(tokens.items, source, allocator);
    defer parser.deinit();
    const ast = try parser.parseProgram();

    var astgen = try AstGen.init(allocator, source);
    defer astgen.deinit();
    try astgen.genProgram(&ast);

    var sema = try Sema.init(allocator, &astgen.zir);
    defer sema.deinit();
    try sema.analyzeProgram();

    var llvm_ir = try LLVMIRGen.init(allocator, &sema.air);
    defer llvm_ir.deinit();
    const ir_code = try llvm_ir.generate();

    return ir_code;
}

// ============================================================================
// Group A: Return (3 tests) - ret void, ret value, function return
// ============================================================================

test "llvm_return_void" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "ret void"));
}

test "llvm_return_value" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn getValue() i32 { return 42; }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "ret"));
}

test "llvm_function_with_return" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn main() i32 { return 0; }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "ret i32"));
}

// ============================================================================
// Group B: Conditionals (3 tests) - br i1, then label, else label
// ============================================================================

test "llvm_conditional_branch" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test(x: i32) { if (x == 1) { } }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "br i1"));
}

test "llvm_then_label" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { if (1 == 1) { const x = 5; } }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "then"));
}

test "llvm_else_label" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { if (1 == 1) { } else { } }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "else"));
}

// ============================================================================
// Group C: Loops (2 tests) - loop label, back-edge br
// ============================================================================

test "llvm_loop_label" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { while (1) { } }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "loop"));
}

test "llvm_loop_back_edge" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { while (1) { const x = 1; } }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "br label"));
}

// ============================================================================
// Group D: Arrays (2 tests) - getelementptr, alloca
// ============================================================================

test "llvm_array_alloca" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "const arr = [1, 2, 3];";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "alloca"));
}

test "llvm_array_getelementptr" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { const arr = [1, 2]; const x = arr[0]; }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "getelementptr"));
}

// ============================================================================
// Group E: Integration (3 tests) - if in function, call, nested
// ============================================================================

test "llvm_if_in_function" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn process(x: i32) { if (x == 5) { } }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "define"));
    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "br i1"));
}

test "llvm_function_call" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn add(a: i32, b: i32) i32 { return a + b; } fn test() { const x = add(1, 2); }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "call i32"));
}

test "llvm_nested_blocks" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};\
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn test() { if (1 == 1) { if (2 == 2) { } } }";
    const ir_code = try compileToLLVMIR(source, allocator);

    try std.testing.expect(std.mem.containsAtLeast(u8, ir_code, 1, "label"));
}

