   229→pub fn typeName(t: Type) []const u8 {
   230→    return switch (t) {
   231→        .void => "void",
   232→        .i32 => "i32",
   233→        .i64 => "i64",
   234→        .f32 => "f32",
   235→        .f64 => "f64",
   236→        .bool => "bool",
   237→        .string => "string",
   238→        .unknown => "unknown",
   239→        .array => "array",
   240→        .function => "function",
   241→    };
   242→}
