   231→/// C 컴파일러 자동 감지 (gcc, clang, cc 순)
   232→fn findCCompiler(allocator: std.mem.Allocator) ![]const u8 {
   233→    const compilers = [_][]const u8{ "gcc", "clang", "cc" };
   234→
   235→    for (compilers) |compiler| {
   236→        const result = try std.process.run(.{
   237→            .allocator = allocator,
   238→            .argv = &[_][]const u8{ compiler, "--version" },
   239→            .capture_stdout = true,
   240→        });
   241→        defer {
   242→            allocator.free(result.stdout);
   243→            allocator.free(result.stderr);
   244→        }
   245→
   246→        if (result.term.Exited == 0) {
   247→            return try allocator.dupe(u8, compiler);
   248→        }
   249→    }
   250→
   251→    return error.NoCCompilerFound;
   252→}
   253→
   254→/// LLVM 컴파일러 자동 감지 (clang, cc 순)
   255→/// clang은 .ll 파일을 직접 바이너리로 컴파일 가능
   256→fn findLLVMCompiler(allocator: std.mem.Allocator) ![]const u8 {
   257→    const compilers = [_][]const u8{ "clang", "cc", "gcc" };
   258→
   259→    for (compilers) |compiler| {
   260→        const result = try std.process.run(.{
   261→            .allocator = allocator,
   262→            .argv = &[_][]const u8{ compiler, "--version" },
   263→            .capture_stdout = true,
   264→        });
   265→        defer {
   266→            allocator.free(result.stdout);
   267→            allocator.free(result.stderr);
   268→        }
   269→
   270→        if (result.term.Exited == 0) {
   271→            return try allocator.dupe(u8, compiler);
   272→        }
   273→    }
   274→
   275→    return error.NoLLVMCompilerFound;
   276→}
   277→
   278→/// 임시 파일명 생성
   279→pub fn generateTempFileName(allocator: std.mem.Allocator, suffix: []const u8) ![]const u8 {
   280→    const timestamp = @as(u64, @bitCast(std.time.nanoTimestamp()));
   281→    return try std.fmt.allocPrint(allocator, "/tmp/zig_tmp_{}{}", .{ timestamp, suffix });
   282→}
   283→
   284→/// 파일 존재 여부 확인
   285→pub fn fileExists(path: []const u8) bool {
   286→    const file = fs.cwd().openFile(path, .{}) catch return false;
   287→    defer file.close();
   288→    return true;
   289→}
   290→
   291→/// 파일 크기 조회
   292→pub fn getFileSize(path: []const u8) !u64 {
   293→    const file = try fs.cwd().openFile(path, .{});
   294→    defer file.close();
   295→    const stat = try file.stat();
   296→    return stat.size;
   297→}
   298→
   299→/// 파일 삭제
   300→pub fn deleteFile(path: []const u8) !void {
   301→    try fs.cwd().deleteFile(path);
   302→}
   303→
   304→/// 파일 복사
   305→pub fn copyFile(src: []const u8, dest: []const u8, allocator: std.mem.Allocator) !void {
   306→    const src_file = try fs.cwd().openFile(src, .{});
   307→    defer src_file.close();
   308→
   309→    const dest_file = try fs.cwd().createFile(dest, .{});
   310→    defer dest_file.close();
   311→
   312→    var buffer: [4096]u8 = undefined;
   313→    while (true) {
   314→        const bytes_read = try src_file.read(&buffer);
   315→        if (bytes_read == 0) break;
   316→        try dest_file.writeAll(buffer[0..bytes_read]);
   317→    }
   318→    _ = allocator;
   319→}
